class FileBuffer {
public:
    FileBuffer(const char* path) {
        FILE* fp = fopen(path, "rb");
        if (!fp) {
            data = nullptr;
            size = 0;
            return;
        }
        fseek(fp, 0, SEEK_END);
        size = ftell(fp);
        fseek(fp, 0, SEEK_SET);
        data = (char*)malloc(size + 1);
        if (!data) {
            fclose(fp);
            size = 0;
            return;
        }
        fread(data, 1, size, fp);
        data[size] = '\0';
        fclose(fp);
    }

    ~FileBuffer() {
        if (data) {
            free(data);
        }
    }

    char* detach() {
        char* tmp = data;
        data = nullptr;
        size = 0;
        return tmp;
    }

    char* getData() { return data; }
    size_t getSize() { return size; }

private:
    char* data;
    size_t size;
};

void processFile(const char* path) {
    FileBuffer buf(path);
    if (buf.getData() == nullptr) {
        printf("Failed to read file\n");
        return;
    }

    char* content = buf.detach();
    if (content == nullptr) {
        return;
    }

    // Simulate some processing
    printf("Content length: %zu\n", strlen(content));

    // Manual free without nulling the local pointer
    free(content);

    // Error handling path - retry logic
    if (strlen(content) > 100) {  // line 51: use-after-free read
        printf("Large file detected\n");
    }

    // Cleanup
    free(content);  // line 55: double free
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        printf("Usage: %s <file>\n", argv[0]);
