    memcpy(pkt->header, buffer, 4);
    pkt->header[4] = '\0';

    pkt->payload_len = buf_len - 4;
    pkt->payload = (char *)malloc(pkt->payload_len);
    if (pkt->payload == NULL) {
        free(pkt->header);
        free(pkt);
        return NULL;
    }
    memcpy(pkt->payload, buffer + 4, pkt->payload_len);

    return pkt;
}

void process_packet(Packet *pkt) {
    if (pkt == NULL || pkt->payload == NULL) {
        return;
    }

    // 打印payload前几个字节
    printf("Payload preview: ");
    for (int i = 0; i < 4 && i < pkt->payload_len; i++) {
        printf("%02x ", (unsigned char)pkt->payload[i]);
    }
    printf("\n");

    // 模拟处理完成后释放payload
    free(pkt->payload);
    // 注意：这里没有将pkt->payload置为NULL
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s <input_file>\n", argv[0]);
        return 1;
    }

    FILE *fp = fopen(argv[1], "rb");
    if (fp == NULL) {
        perror("fopen");
        return 1;
    }

    char buffer[MAX_PACKET_SIZE];
    int len = fread(buffer, 1, MAX_PACKET_SIZE, fp);
    fclose(fp);

    if (len <= 0) {
        printf("Empty file\n");
        return 1;
    }

    Packet *pkt = parse_packet(buffer, len);
    if (pkt == NULL) {
        printf("Parse failed\n");
        return 1;
    }

    process_packet(pkt);

    // 漏洞触发点：再次使用已释放的payload
    if (pkt->payload != NULL) {
        printf("Payload length: %d\n", pkt->payload_len);
