class BufferManager {
public:
    BufferManager(size_t capacity) : capacity_(capacity), data_(new char[capacity]) {
        std::memset(data_, 0, capacity_);
    }

    ~BufferManager() {
        std::lock_guard<std::mutex> lock(mutex_);
        delete[] data_;
    }

    // 写入数据，不检查长度
    bool write(const char* input, size_t len) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (!data_) return false;
        // 漏洞：未检查 len 是否超过 capacity_
        std::memcpy(data_, input, len);  // line 19: 越界写入
        return true;
    }

    size_t size() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return capacity_;
    }

private:
    size_t capacity_;
    char* data_;
    mutable std::mutex mutex_;
};

// 模拟并发生产者，写入固定数据
void producer(BufferManager& buf, const char* payload, size_t len) {
    buf.write(payload, len);
}

// 模拟并发消费者，仅读取大小
void consumer(BufferManager& buf) {
    volatile size_t s = buf.size();
    (void)s;
}

int main() {
    BufferManager buf(16);  // 缓冲区只有 16 字节
    const char* payload = "This is a much longer payload than the buffer can hold!";
    size_t payload_len = std::strlen(payload);  // 56 字节

    // 启动多个线程，制造并发写入场景
    std::vector<std::thread> threads;
    for (int i = 0; i < 4; ++i) {
        threads.emplace_back(producer, std::ref(buf), payload, payload_len);
        threads.emplace_back(consumer, std::ref(buf));
    }

    for (auto& t : threads) {
        t.join();
    }
    return 0;
}
