bool ReadFileHeader(const std::string& path, std::vector<uint8_t>& out, size_t n) {
    std::ifstream file(path, std::ios::binary);
    if (!file.is_open()) {
        return false;
    }

    // 获取文件大小
    file.seekg(0, std::ios::end);
    std::streampos fileSize = file.tellg();
    file.seekg(0, std::ios::beg);

    // 限制读取不超过文件实际大小
    size_t bytesToRead = (n < static_cast<size_t>(fileSize)) ? n : static_cast<size_t>(fileSize);
    out.resize(bytesToRead);

    if (bytesToRead > 0) {
        file.read(reinterpret_cast<char*>(out.data()), bytesToRead);
    }
    return true;
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        std::cerr << "Usage: " << argv[0] << " <file>\n";
        return 1;
    }

    std::vector<uint8_t> header;
    if (!ReadFileHeader(argv[1], header, 64)) {
        std::cerr << "Failed to read file\n";
        return 1;
    }

    // 解析文件头中的长度字段（前4字节，小端序）
    if (header.size() >= 4) {
