#include <linux/kernel.h>
#include <linux/module.h>
#include <linux/device.h>
#include <linux/slab.h>
#include <linux/uaccess.h>

#define DRIVER_NAME "vuln_dev"
#define IOCTL_SET_BUF _IOW(0x10, 0x01, unsigned long)
#define BUF_SIZE 128

static char *device_buf;
static int device_open_count;

static int dev_open(struct inode *inode, struct file *filp)
{
    if (device_open_count > 0)
        return -EBUSY;
    device_open_count++;
    return 0;
}

static int dev_release(struct inode *inode, struct file *filp)
{
    device_open_count--;
    return 0;
}

static long dev_ioctl(struct file *filp, unsigned int cmd, unsigned long arg)
{
    char *user_buf;
    size_t user_len;

    if (cmd != IOCTL_SET_BUF)
        return -EINVAL;

    if (copy_from_user(&user_buf, (void __user *)arg, sizeof(user_buf)))
        return -EFAULT;

    user_len = strnlen(user_buf, BUF_SIZE);

    if (user_len >= BUF_SIZE)
        return -EINVAL;

    if (device_buf)
        kfree(device_buf);

    device_buf = kmalloc(BUF_SIZE, GFP_KERNEL);
    if (!device_buf)
        return -ENOMEM;

    memcpy(device_buf, user_buf, user_len);
    device_buf[user_len] = '\0';

    return 0;
}

static struct file_operations fops = {
    .owner = THIS_MODULE,
    .open = dev_open,
    .release = dev_release,
    .unlocked_ioctl = dev_ioctl,
};

static struct miscdevice misc_dev = {
    .minor = MISC_DYNAMIC_MINOR,
    .name = DRIVER_NAME,
    .fops = &fops,
};

static int __init dev_init(void)
{
    device_buf = NULL;
    device_open_count = 0;
    return misc_register(&misc_dev);
}

static void __exit dev_exit(void)
{
    if (device_buf)
        kfree(device_buf);
    misc_deregister(&misc_dev);
}

module_init(dev_init);
module_exit(dev_exit);
MODULE_LICENSE("GPL");
