#define DEVICE_NAME "vuln_dev"
#define BUF_SIZE 128

static int device_open(struct inode *inode, struct file *file)
{
    char *kernel_buf = kmalloc(BUF_SIZE, GFP_KERNEL);
    if (!kernel_buf)
        return -ENOMEM;
    file->private_data = kernel_buf;
    return 0;
}

static ssize_t device_read(struct file *file, char __user *user_buf,
                           size_t count, loff_t *offset)
{
    char *kernel_buf = file->private_data;
    size_t bytes_to_read;
    int ret;

    if (count > BUF_SIZE)
        count = BUF_SIZE;

    bytes_to_read = count;
    if (bytes_to_read > 0)
    {
        ret = copy_to_user(user_buf, kernel_buf, bytes_to_read);
        if (ret)
            return -EFAULT;
    }
    return bytes_to_read;
}

static ssize_t device_write(struct file *file, const char __user *user_buf,
                            size_t count, loff_t *offset)
{
    char *kernel_buf = file->private_data;
    size_t bytes_to_write;

    if (count > BUF_SIZE)
        count = BUF_SIZE;

    bytes_to_write = count;
    if (bytes_to_write > 0)
    {
        if (copy_from_user(kernel_buf, user_buf, bytes_to_write))
            return -EFAULT;
    }
    return bytes_to_write;
}

static int device_release(struct inode *inode, struct file *file)
{
    char *kernel_buf = file->private_data;
    kfree(kernel_buf);
    return 0;
}

