// 模拟图像解码器中的尺寸计算与缓冲区分配
struct ImageHeader {
    uint32_t width;
    uint32_t height;
    uint16_t channels;
};

// 从文件读取头部（假设已实现）
bool read_header(FILE* fp, ImageHeader* hdr) {
    return fread(hdr, sizeof(ImageHeader), 1, fp) == 1;
}

// 分配像素缓冲区
unsigned char* allocate_pixels(uint32_t width, uint32_t height, uint16_t channels) {
    // 第14行：整数溢出点 - width * height * channels 可能超过 uint32_t 范围
    uint32_t total = width * height * channels;

    // 第16行：溢出后 total 变小，分配过小缓冲区
    unsigned char* buf = (unsigned char*)malloc(total);
    if (!buf) return nullptr;

    // 实际写入时按真实尺寸计算，导致堆溢出
    return buf;
}

bool decode_image(const char* filename) {
    FILE* fp = fopen(filename, "rb");
    if (!fp) return false;

    ImageHeader hdr;
    if (!read_header(fp, &hdr)) {
        fclose(fp);
        return false;
    }

    // 第28行：恶意构造 width=65536, height=65536, channels=4
    // 65536 * 65536 * 4 = 17,179,869,184 > 2^32，溢出为 0
    unsigned char* pixels = allocate_pixels(hdr.width, hdr.height, hdr.channels);
    if (!pixels) {
        fclose(fp);
        return false;
    }

    // 第34行：按未溢出的真实大小读取数据，写入溢出后的缓冲区
    size_t real_size = (size_t)hdr.width * hdr.height * hdr.channels;
    if (fread(pixels, 1, real_size, fp) != real_size) {
        free(pixels);
        fclose(fp);
        return false;
    }

    // 模拟解码处理
    for (uint32_t i = 0; i < hdr.width * hdr.height; ++i) {
        pixels[i * hdr.channels] = 0;  // 第40行：越界写
    }

    free(pixels);
    fclose(fp);
    return true;
}

int main(int argc, char** argv) {
    if (argc < 2) return 1;
    return decode_image(argv[1]) ? 0 : 1;
}
