#include <cstdio>

class SharedBuffer {
public:
    SharedBuffer() : data(nullptr), lock(PTHREAD_MUTEX_INITIALIZER), ref_count(0) {}
    ~SharedBuffer() { pthread_mutex_destroy(&lock); }

    bool init(size_t size) {
        pthread_mutex_lock(&lock);
        if (data == nullptr) {
            data = (char*)malloc(size);
            if (data) ref_count = 1;
        } else {
            ref_count++;
        }
        pthread_mutex_unlock(&lock);
        return data != nullptr;
    }

