static int parse_header_field(packet_t *pkt, size_t offset,
                              char *out, size_t out_sz) {
    if (offset >= pkt->len) return -1;

    size_t field_len = (size_t)pkt->data[offset];  /* 1-byte length prefix */
    if (offset + 1 + field_len > pkt->len) return -1;

    /* VULN: no check that field_len < out_sz before memcpy */
    memcpy(out, pkt->data + offset + 1, field_len);  // line 19
    out[field_len] = '\0';                            // line 20
    return 0;
}

/* Extract two header fields into caller-provided buffers. */
int parse_packet(packet_t *pkt, char *user, size_t user_sz,
                 char *path, size_t path_sz) {
    if (!pkt || !user || !path) return -1;

    size_t hdr_end = (size_t)pkt->data[0] & 0x3F;  /* lower 6 bits = header size */
    if (hdr_end > MAX_HDR_LEN || hdr_end + 2 > pkt->len) return -1;

    /* Field 1: starts at offset 1 */
    if (parse_header_field(pkt, 1, user, user_sz) != 0) return -1;

    /* Field 2: starts after field 1's length byte + field data */
    size_t f1_len = (size_t)pkt->data[1];
    size_t f2_offset = 2 + f1_len;
    if (f2_offset >= hdr_end) return -1;

    if (parse_header_field(pkt, f2_offset, path, path_sz) != 0) return -1;
    return 0;
