static int drv_ioctl_release(struct drv_context *ctx, unsigned long arg)
{
    void *tmp;

    mutex_lock(&ctx->lock);
    if (!ctx->data) {
        mutex_unlock(&ctx->lock);
        return -EINVAL;
    }

    tmp = ctx->data;
    ctx->data = NULL;
    mutex_unlock(&ctx->lock);

    kfree(tmp);
    return 0;
}

static int drv_ioctl_read(struct drv_context *ctx, char __user *buf)
{
    int ret = -EFAULT;

    mutex_lock(&ctx->lock);
    if (!ctx->data)
        goto out_unlock;

    if (copy_to_user(buf, ctx->data, ctx->size)) {
        ret = -EFAULT;
        goto out_unlock;
    }
    ret = 0;

out_unlock:
    mutex_unlock(&ctx->lock);
    return ret;
}

static int drv_ioctl_process(struct drv_context *ctx, unsigned long arg)
{
    /* 调用者保证 ctx 有效 */
    drv_ioctl_release(ctx, arg);
    /* 释放后继续使用 ctx->data，触发 UAF */
    return drv_ioctl_read(ctx, (char __user *)arg);
