// Parse header and extract a variable-length field
std::string extractField(const std::string& path) {
    std::ifstream file(path, std::ios::binary);
    if (!file.is_open()) return "";

    uint8_t header[HEADER_SIZE];
    if (readExact(file, header, HEADER_SIZE) != HEADER_SIZE) return "";
    if (header[0] != 0xDE || header[1] != 0xAD) return "";

    // field length is stored in bytes 4-5 (little-endian)
    uint16_t fieldLen = static_cast<uint16_t>(header[4]) |
                        (static_cast<uint16_t>(header[5]) << 8);

    // Validate field length against a sane maximum
    if (fieldLen > MAX_FIELD_SIZE) return "";

    // Allocate buffer for the field content
    std::vector<uint8_t> buffer(fieldLen + 1, 0); // +1 for null terminator
    size_t bytesRead = readExact(file, buffer.data(), fieldLen);

    // Vulnerability: if file is truncated, bytesRead < fieldLen, but we still
    // treat buffer as a null-terminated string. The buffer was zero-initialized,
    // so trailing bytes are 0, but the string may be shorter than expected.
