    // checking bounds when bytesRead == fieldLen (which is fine), but the
    // caller may use the length field without verifying actual bytes read.
    // The OOB read occurs in the caller when it assumes the field is fieldLen
    // bytes long but the file was truncated. Here we demonstrate the OOB
    // read in the string constructor.
    std::string result(reinterpret_cast<char*>(buffer.data()), fieldLen);
    return result;
}

