bool decodeRLE(const uint8_t* src, size_t src_len, uint8_t* dst, size_t dst_cap) {
    size_t src_pos = 0, dst_pos = 0;
    while (src_pos < src_len) {
        uint8_t marker = src[src_pos++];
        uint8_t run_len = (marker & 0x7F) + 1;
        if (marker & 0x80) {
            // Literal run: copy run_len bytes directly
            if (src_pos + run_len > src_len) return false;
            if (dst_pos + run_len > dst_cap) return false;
            memcpy(dst + dst_pos, src + src_pos, run_len);
            src_pos += run_len;
            dst_pos += run_len;
        } else {
            // Repeated byte run
            if (src_pos >= src_len) return false;
            if (dst_pos + run_len > dst_cap) return false;
            memset(dst + dst_pos, src[src_pos++], run_len);
            dst_pos += run_len;
        }
    }
    return true;
