int decode_scanline(const uint8_t* rle, size_t rle_len,
                    uint8_t* out, size_t out_cap) {
    size_t pos = 0, opos = 0;
    while (pos < rle_len) {
        uint8_t ctrl = rle[pos++];
        if (ctrl & 0x80) {           // literal run
            uint8_t n = ctrl & 0x7F;
            if (pos + n > rle_len || opos + n > out_cap) return -1;
            memcpy(out + opos, rle + pos, n);
            pos += n; opos += n;
        } else {                      // repeat run
            uint8_t n = ctrl;
            if (pos >= rle_len) return -1;
            uint8_t val = rle[pos++];
            if (opos + n > out_cap) return -1;
            memset(out + opos, val, n);
            opos += n;
        }
    }
    return 0;
}

