    unsigned char data[];
} fw_header_t;

int verify_firmware(const char *path) {
    int fd = open(path, O_RDONLY);
    if (fd < 0) return -1;

    struct stat st;
    if (fstat(fd, &st) < 0) {
        close(fd);
        return -1;
    }

    if (st.st_size > MAX_FW_SIZE) {
        close(fd);
        return -1;
    }

    fw_header_t *hdr = malloc(st.st_size);
    if (!hdr) {
        close(fd);
        return -1;
    }

    if (read(fd, hdr, st.st_size) != st.st_size) {
        free(hdr);
        close(fd);
        return -1;
    }
    close(fd);

    unsigned int calc = 0;
    for (unsigned int i = 0; i < st.st_size; i++) {
        calc += ((unsigned char*)hdr)[i];
    }

    if (calc != hdr->checksum) {
        free(hdr);
        return -1;
    }

    /* 校验通过，模拟固件安装 */
    printf("Firmware %s verified, installing...\n", hdr->version);
    free(hdr);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <firmware_path>\n", argv[0]);
        return 1;
    }

    /* 攻击者可通过符号链接替换此处的config.bin */
    if (verify_firmware(CONFIG_PATH) == 0) {
        printf("Installation complete.\n");
    } else {
        printf("Verification failed.\n");
    }
    return 0;
}
