size_t calc_row_stride(int width, int channels, int align_bits) {
    int bits_per_pixel = channels * 8;
    size_t row_bits = static_cast<size_t>(width) * bits_per_pixel;
    size_t align_mask = (static_cast<size_t>(1) << align_bits) - 1;
    // 向上对齐到 2^align_bits 字节
    return (row_bits + 7) / 8 + ((align_mask) & ~(row_bits / 8)); // 简化对齐逻辑
}

bool decode_raw_frame(const uint8_t* input, size_t input_size,
                      int width, int height, int channels,
                      int align_bits, DecodedFrame& out) {
    if (width <= 0 || height <= 0 || channels <= 0 || channels > 4) {
        return false;
    }
    if (align_bits < 0 || align_bits > 6) {
        return false;
    }

    size_t row_stride = calc_row_stride(width, channels, align_bits);
    // 潜在整数溢出点：width * height * channels 可能溢出 size_t
    size_t total_size = row_stride * static_cast<size_t>(height);

    // 检查输入是否足够（但 total_size 可能已溢出成小值）
    if (input_size < total_size) {
        return false;
    }

    uint8_t* buffer = new uint8_t[total_size];  // 若 total_size 溢出，此处分配过小
    memcpy(buffer, input, total_size);

    out.data = buffer;
    out.size = total_size;
    out.width = width;
    out.height = height;
    out.channels = channels;
    return true;
}

