    int w = static_cast<int>(header[0]) | (static_cast<int>(header[1]) << 8);
    int h = static_cast<int>(header[2]) | (static_cast<int>(header[3]) << 8);
    int ch = static_cast<int>(header[4]);
    int align = static_cast<int>(header[5]) & 0x0F;

    // 无上限检查，恶意值可导致 w*h 极大
    return decode_raw_frame(header + 16, header_len - 16, w, h, ch, align, frame);
