static int copy_from_user_safe(struct io_buffer *buf, const char __user *user_buf, size_t n)
{
    if (!buf || !user_buf)
        return -EINVAL;
    if (n > MAX_DATA_SIZE)
        return -EINVAL;
    if (mutex_lock_interruptible(&buf->lock))
        return -ERESTARTSYS;
    if (buf->len + n > MAX_DATA_SIZE) {
        mutex_unlock(&buf->lock);
        return -EINVAL;
    }
    /* Vulnerability: no check for buf->data being NULL (freed elsewhere) */
    if (copy_from_user(buf->data + buf->len, user_buf, n)) {
        mutex_unlock(&buf->lock);
        return -EFAULT;
    }
    buf->len += n;
    mutex_unlock(&buf->lock);
    return 0;
}

static void free_buffer(struct io_buffer *buf)
{
    mutex_lock(&buf->lock);
    kfree(buf->data);
    buf->data = NULL;  /* safe: NULL after free */
    buf->len = 0;
    mutex_unlock(&buf->lock);
}

static int ioctl_append(struct io_buffer *buf, const char __user *user_buf, size_t n)
{
    if (!buf)
        return -EINVAL;
    /* Race window: free_buffer can be called concurrently from another thread */
    return copy_from_user_safe(buf, user_buf, n);
}

static int ioctl_free(struct io_buffer *buf)
{
    if (!buf)
        return -EINVAL;
    free_buffer(buf);
    return 0;
}

