    width = reader.readBits(16);
    height = reader.readBits(16);
    if (width <= 0 || height <= 0 || width > 4096 || height > 4096) {
        return false;
    }

    // Calculate pixel buffer size (RGBA format, 4 bytes per pixel)
    size_t totalPixels = static_cast<size_t>(width) * static_cast<size_t>(height);
    size_t bufferSize = totalPixels * 4;

    // Validate against remaining stream size (each pixel needs 4 bytes of data)
    if (bufferSize > compressedSize * 4) {  // heuristic: compressed ratio check
        return false;
    }

    rawPixels.resize(bufferSize);

    // Decompression loop
    size_t pixelIndex = 0;
    while (pixelIndex < totalPixels && reader.canRead(8)) {
        uint8_t tag = static_cast<uint8_t>(reader.readBits(8));
        int runLength;

        if (tag & 0x80) {
            // Run-length encoding: high bit set, next 7 bits = run length
            runLength = static_cast<int>(tag & 0x7F) + 1;
            if (runLength > static_cast<int>(totalPixels - pixelIndex)) {
                return false;  // run exceeds remaining pixels
            }

            uint8_t r = static_cast<uint8_t>(reader.readBits(8));
            uint8_t g = static_cast<uint8_t>(reader.readBits(8));
            uint8_t b = static_cast<uint8_t>(reader.readBits(8));
            uint8_t a = static_cast<uint8_t>(reader.readBits(8));

            for (int i = 0; i < runLength; i++) {
                size_t offset = (pixelIndex + i) * 4;
                rawPixels[offset] = r;
                rawPixels[offset + 1] = g;
                rawPixels[offset + 2] = b;
                rawPixels[offset + 3] = a;
            }
            pixelIndex += runLength;
        } else {
            // Direct pixel: low 7 bits = number of raw pixels
            int count = static_cast<int>(tag & 0x7F) + 1;
            if (count > static_cast<int>(totalPixels - pixelIndex)) {
                return false;
            }

            for (int i = 0; i < count; i++) {
                if (!reader.canRead(32)) {
                    return false;
