        ssize_t total = 0;
        while (total < static_cast<ssize_t>(chunk_len)) {
            ssize_t n = pread(fd_, out.data() + total, chunk_len - total, offset + total);
            if (n <= 0) {
                if (n == 0) break;  // EOF
                return -1;
            }
            total += n;
        }
        out.resize(total);
        return total;
    }

    void SetBlockSize(uint32_t sz) {
        if (sz > 0 && sz <= MAX_BLOCK_SIZE) {
            block_size_ = sz;
