    uint32_t frame_size = (input[offset] << 24) | (input[offset + 1] << 16) |
                          (input[offset + 2] << 8) | input[offset + 3];
    offset += 4;

    if (frame_size == 0 || offset + frame_size > input.size()) {
        return nullptr;
    }

    DecodedFrame* frame = new DecodedFrame();
    frame->data = new uint8_t[frame_size];
