    frame->size = frame_size;
    frame->width = 0;   // 简化：实际从帧头解析
    frame->height = 0;
    offset += frame_size;
    return frame;
}

void release_frame(DecodedFrame* frame) {
    if (frame) {
        delete[] frame->data;
        delete frame;
    }
}

