class RingBuffer {
public:
    explicit RingBuffer(size_t capacity) : data_(capacity), head_(0), tail_(0), size_(0), capacity_(capacity) {}

    void push(int value) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (size_ == capacity_) {
            return; // buffer full, drop
        }
        data_[tail_] = value;
        tail_ = (tail_ + 1) % capacity_;
        ++size_;
    }

    int pop() {
        std::lock_guard<std::mutex> lock(mutex_);
        if (size_ == 0) {
            return -1; // empty sentinel
        }
        int value = data_[head_];
        head_ = (head_ + 1) % capacity_;
        --size_;
        return value;
    }

    // 安全版本：带边界检查的批量读取
    bool peek_range(size_t offset, size_t count, std::vector<int>& out) const {
        std::lock_guard<std::mutex> lock(mutex_);
        if (offset >= size_ || count == 0 || offset + count > size_) {
            return false; // 边界检查：防止越界读取
        }
        out.reserve(count);
        for (size_t i = 0; i < count; ++i) {
            size_t idx = (head_ + offset + i) % capacity_;
            out.push_back(data_[idx]);
        }
        return true;
    }

private:
    std::vector<int> data_;
    size_t head_;
    size_t tail_;
    size_t size_;
    size_t capacity_;
    mutable std::mutex mutex_;
};

void producer(RingBuffer& buf, int start, int count) {
    for (int i = 0; i < count; ++i) {
        buf.push(start + i);
    }
}

