// 模拟解码器输入流结构
struct DecoderStream {
    const uint8_t* data;
    size_t size;
    size_t pos;
};

// 从流中读取变长整数（LEB128风格），返回读取字节数或-1
int read_varint(DecoderStream* stream, uint32_t* out) {
    uint32_t result = 0;
    int shift = 0;
    size_t start = stream->pos;

    while (shift < 32) {
        if (stream->pos >= stream->size) return -1; // 边界检查
        uint8_t byte = stream->data[stream->pos++];
        result |= (uint32_t)(byte & 0x7F) << shift;
        if (!(byte & 0x80)) {
            *out = result;
            return (int)(stream->pos - start);
        }
        shift += 7;
    }
    return -1; // 溢出
}

// 解码一帧：首字节是类型，随后是变长长度，最后是像素数据
bool decode_frame(const uint8_t* input, size_t input_size, 
                  std::vector<uint8_t>* output) {
    DecoderStream stream = {input, input_size, 0};

    if (stream.pos >= stream.size) return false;
    uint8_t type = stream.data[stream.pos++];

    uint32_t length = 0;
    if (read_varint(&stream, &length) < 0) return false;

    // 长度合理性校验：不能超过剩余输入
    if (length > (stream.size - stream.pos)) return false;

    // 帧类型0x01表示原始RGB数据，需要分配输出缓冲
    if (type == 0x01) {
        // 输出缓冲按length分配，但解码时按3字节像素写入
        output->resize(length);
        if (length == 0) return true;

        // 逐像素解码：每个像素3字节，但length是字节数
        uint8_t* dst = output->data();
        size_t pixel_count = length / 3;
        const uint8_t* src = stream.data + stream.pos;

        // 安全：每像素写入前检查剩余空间（防御性冗余）
        for (size_t i = 0; i < pixel_count; i++) {
            if ((size_t)(dst - output->data()) + 3 > output->size()) break;
            dst[0] = src[0] & 0x7F;  // 模拟解码变换
            dst[1] = src[1] << 1;
            dst[2] = src[2] ^ 0x55;
            dst += 3;
            src += 3;
        }
        return true;
    }

    // 其他类型直接复制
    output->assign(stream.data + stream.pos, 
                   stream.data + stream.pos + length);
    return true;
}

// 对外API：解码完整图像
bool decode_image(const std::vector<uint8_t>& compressed,
                  std::vector<uint8_t>* rgba_out) {
    if (compressed.empty()) return false;

    // 调用帧解码（单帧场景）
    std::vector<uint8_t> frame;
    if (!decode_frame(compressed.data(), compressed.size(), &frame)) {
        return false;
    }

    // 转换为RGBA（此处简化，实际会做格式转换）
    rgba_out->assign(frame.begin(), frame.end());
    return true;
}
