class Counter {
public:
    explicit Counter(uint32_t initial) : value_(initial) {}

    // Thread-safe increment with overflow check
    bool safe_increment() {
        uint32_t current = value_.load(std::memory_order_relaxed);
        do {
            if (current == UINT32_MAX) {
                return false;  // Overflow would occur; reject
            }
        } while (!value_.compare_exchange_weak(current, current + 1,
                                               std::memory_order_relaxed));
        return true;
    }

