    }

private:
    std::atomic<uint32_t> value_;
};

void worker(Counter& counter, int iterations, int& success_count) {
    for (int i = 0; i < iterations; ++i) {
        if (counter.safe_increment()) {
            ++success_count;
        }
    }
}

