    constexpr int kIterations = 100000;
    // Start near the max to test the overflow guard
    Counter counter(UINT32_MAX - 1000);

    std::vector<std::thread> threads;
    std::vector<int> results(kThreads, 0);

    for (int t = 0; t < kThreads; ++t) {
        threads.emplace_back(worker, std::ref(counter), kIterations, std::ref(results[t]));
