// Decodes a run-length encoded (RLE) pixel row into a raw RGBA buffer.
// The encoded format: [count:uint8][value:uint8] pairs, terminated by count=0.
// Expected output: exactly width*4 bytes (RGBA per pixel).
bool DecodeRleRow(const std::vector<uint8_t>& encoded, size_t& offset,
                  uint8_t* rawRow, size_t width) {
    const size_t rowBytes = width * 4;
    size_t written = 0;

    while (offset < encoded.size()) {
        uint8_t count = encoded[offset++];
        if (count == 0) break; // end of row marker

        if (offset >= encoded.size()) return false; // missing value byte
        uint8_t value = encoded[offset++];

        size_t chunk = static_cast<size_t>(count) * 4;
        if (chunk > rowBytes - written) {
            return false; // would overflow the row buffer
        }
        std::memset(rawRow + written, value, chunk);
        written += chunk;

        if (written == rowBytes) break; // row fully filled
    }
    return written == rowBytes;
}

// Public entry point: decodes a full image frame.
// frameData layout: [width:uint32][height:uint32][RLE rows...]
bool DecodeFrame(const std::vector<uint8_t>& frameData,
                 std::vector<uint8_t>& outPixels) {
    if (frameData.size() < 8) return false;

    uint32_t width, height;
    std::memcpy(&width, frameData.data(), 4);
    std::memcpy(&height, frameData.data() + 4, 4);
    if (width == 0 || height == 0 || width > 4096 || height > 4096) {
        return false;
    }

    const size_t totalPixels = static_cast<size_t>(width) * height;
    if (totalPixels > (1ULL << 24)) return false; // sanity cap

    outPixels.resize(totalPixels * 4);
    size_t offset = 8;

    for (uint32_t y = 0; y < height; ++y) {
        if (!DecodeRleRow(frameData, offset, outPixels.data() + y * width * 4, width)) {
            return false;
        }
    }
    return true;
}
