        data = new int[n]();
    }

    ~SafeBuffer() {
        std::lock_guard<std::mutex> lock(mtx);
        delete[] data;
        data = nullptr;  // 防御：置 NULL 防止悬垂指针
    }

    // 线程安全的写入操作
    bool write(size_t index, int value) {
        std::lock_guard<std::mutex> lock(mtx);
        if (index >= size) {
