    bool read(size_t index, int& out) {
        std::lock_guard<std::mutex> lock(mtx);
        if (index >= size) {
            return false;
        }
        out = data[index];
        return true;
    }

    // 禁止拷贝和赋值，避免双重释放
    SafeBuffer(const SafeBuffer&) = delete;
    SafeBuffer& operator=(const SafeBuffer&) = delete;
