public:
    DecoderContext() : current_frame_(nullptr), buffer_(nullptr), buffer_size_(0) {}
    ~DecoderContext() { cleanup(); }

    // Allocate internal buffer for decoded PCM data
    bool allocate_buffer(size_t size) {
        if (buffer_) delete[] buffer_;
        buffer_ = new int16_t[size];
        buffer_size_ = size;
        return buffer_ != nullptr;
    }

    // Process incoming encoded chunk, returns frame reference
    AudioFrame* process_chunk(const uint8_t* data, size_t len) {
        if (!data || len == 0) return nullptr;

        // Simulate decoding: allocate frame and copy samples
        AudioFrame* frame = new AudioFrame;
        frame->sample_count = len / 2;
        frame->sample_rate = 44100;
        frame->is_valid = false;

        if (buffer_size_ < frame->sample_count) {
            delete frame;
            return nullptr;
        }

        memcpy(buffer_, data, len);
        frame->samples = buffer_;
        frame->is_valid = true;

        // Store previous frame pointer for lifecycle management
        if (current_frame_) {
            // Release previous frame without deleting samples (owned by buffer)
            delete current_frame_;
        }
        current_frame_ = frame;
        return frame;
    }

    // Get current frame's sample at index
    int16_t get_sample(AudioFrame* frame, size_t index) {
        // Defensive check: verify frame validity and index bounds
        if (!frame || !frame->is_valid) {
            throw std::runtime_error("Invalid frame access");
        }
        if (index >= frame->sample_count) {
            throw std::out_of_range("Sample index out of bounds");
        }
        return frame->samples[index];
    }

    void cleanup() {
        delete[] buffer_;
        buffer_ = nullptr;
        buffer_size_ = 0;
        delete current_frame_;
        current_frame_ = nullptr;
    }

private:
    AudioFrame* current_frame_;
    int16_t* buffer_;
    size_t buffer_size_;
};

