    static int calculateBlockCount(long long fileSize) {
        // 检查溢出：如果 fileSize 超过 INT_MAX * 4096，则截断
        const long long MAX_SAFE_SIZE = static_cast<long long>(INT32_MAX) * 4096LL;
        if (fileSize > MAX_SAFE_SIZE) {
            return -1;  // 表示溢出，调用方处理错误
        }
        // 向上取整计算块数
        int blocks = static_cast<int>((fileSize + 4095) / 4096);
        return blocks;
    }

    // 写入文件并返回写入的字节数
    static long long writeFile(const std::string& path, const char* data, size_t size) {
        int fd = open(path.c_str(), O_WRONLY | O_CREAT | O_TRUNC, 0644);
        if (fd == -1) {
            std::cerr << "open failed: " << strerror(errno) << std::endl;
            return -1;
        }

        long long totalWritten = 0;
        size_t offset = 0;
        while (offset < size) {
            ssize_t written = write(fd, data + offset, size - offset);
            if (written == -1) {
                if (errno == EINTR) continue;
                std::cerr << "write failed: " << strerror(errno) << std::endl;
                close(fd);
                return -1;
            }
            offset += static_cast<size_t>(written);
            totalWritten += written;
        }

        close(fd);
        return totalWritten;
    }

    // 检查文件是否存在
    static bool fileExists(const std::string& path) {
