    ImageRowDecoder(const uint8_t* data, size_t len)
        : data_(data), len_(len) {}

    // 解码一行像素，输出到 out_buf
    // 每像素 3 字节 (RGB)，width 为像素数
    bool DecodeRow(uint8_t* out_buf, size_t out_capacity, size_t width) {
        if (width > out_capacity / 3) {
            std::cerr << "Buffer too small\n";
            return false;
        }

        // 从输入流读取行头 (2 字节长度 + 1 字节标志)
        if (len_ < 3) {
            std::cerr << "Truncated header\n";
            return false;
        }
        uint16_t row_len = (data_[0] << 8) | data_[1];
        uint8_t flags = data_[2];

        // 检查输入长度是否足够
        if (3 + row_len > len_) {
            std::cerr << "Truncated row data\n";
            return false;
        }

        // 根据标志位决定解码模式
        if (flags & 0x01) {
            // 压缩模式：每 3 字节表示 2 个像素 (RLE-like)
            size_t src_idx = 3;
            size_t dst_idx = 0;
            while (src_idx + 2 < 3 + row_len && dst_idx + 5 < width * 3) {
                uint8_t r = data_[src_idx];
                uint8_t g = data_[src_idx + 1];
                uint8_t b = data_[src_idx + 2];
                out_buf[dst_idx] = r;
                out_buf[dst_idx + 1] = g;
                out_buf[dst_idx + 2] = b;
                // 复制到下一个像素
                out_buf[dst_idx + 3] = r;
                out_buf[dst_idx + 4] = g;
                out_buf[dst_idx + 5] = b;
                src_idx += 3;
                dst_idx += 6;
            }
        } else {
            // 原始模式：直接拷贝
            size_t copy_len = row_len;
            if (copy_len > width * 3) {
                copy_len = width * 3;
            }
            memcpy(out_buf, data_ + 3, copy_len);
        }
        return true;
    }

private:
    const uint8_t* data_;
    size_t len_;
};

