    bool writeAt(size_t offset, const char* data, size_t len) {
        std::lock_guard<std::mutex> lock(mtx);
        if (offset >= capacity || len > capacity - offset) {
            return false;  // 边界检查防止越界
        }
        memcpy(buffer + offset, data, len);
        return true;
    }

