#define MAX_PKT_SIZE 1024
#define HDR_SIZE 8

typedef struct {
    uint8_t *data;
    size_t len;
} packet_t;

static int parse_packet(const uint8_t *buf, size_t buf_len, packet_t *out) {
    if (buf_len < HDR_SIZE) {
        return -1;
    }
    uint16_t payload_len = (uint16_t)((buf[2] << 8) | buf[3]);
    if (payload_len > buf_len - HDR_SIZE) {
        return -1;
    }
    out->data = (uint8_t *)malloc(payload_len);
    if (!out->data) {
        return -1;
    }
    memcpy(out->data, buf + HDR_SIZE, payload_len);
    out->len = payload_len;
    return 0;
}

int process_network_packet(const uint8_t *raw, size_t raw_len) {
    packet_t pkt = {0};
    if (parse_packet(raw, raw_len, &pkt) != 0) {
        return -1;
    }

    if (pkt.len < 4) {
        free(pkt.data);
        return -1;
    }

    uint32_t seq = (uint32_t)((pkt.data[0] << 24) | (pkt.data[1] << 16) |
                              (pkt.data[2] << 8) | pkt.data[3]);
