bool decodeRawFrame(const uint8_t* compressed, size_t compressedSize,
                    uint32_t expectedWidth, uint32_t expectedHeight,
                    DecodedFrame& outFrame) {
    // Header: 4 bytes magic, 4 bytes width, 4 bytes height, 4 bytes channels
    const size_t headerSize = 16;
    if (compressedSize < headerSize) {
        return false;
    }

    uint32_t width = expectedWidth;
    uint32_t height = expectedHeight;
    uint8_t channels = 4; // RGBA fixed

    // Validate dimensions against a sane limit (e.g., 8K max)
    if (width == 0 || height == 0 || width > 7680 || height > 4320) {
        return false;
    }

    // Compute pixel count using 64-bit to avoid 32-bit overflow
    uint64_t pixelCount = static_cast<uint64_t>(width) * static_cast<uint64_t>(height);
    if (pixelCount == 0) {
        return false;
    }

    // Check for overflow in total byte size: pixelCount * channels
    // channels is uint8_t (max 255), but we cap it via multiplication check
    if (channels > 255 / pixelCount) { // Division-based check: if channels > max/pixelCount => overflow
        return false;
    }
    size_t totalSize = static_cast<size_t>(pixelCount) * channels;

    // Verify compressed buffer has enough payload
    if (compressedSize < headerSize + totalSize) {
        return false;
    }

    // Allocate output buffer
    outFrame.data.resize(totalSize);

    // Copy payload (skip header)
    const uint8_t* payload = compressed + headerSize;
    std::memcpy(outFrame.data.data(), payload, totalSize);

    // Set metadata
    outFrame.width = width;
    outFrame.height = height;
    outFrame.channels = channels;

    return true;
}
