    uint32_t magic;
    uint32_t data_size;
    uint32_t reserved[2];
};

// 跨函数：读取文件头并进行边界校验
bool parseHeader(std::ifstream& file, FileHeader& header) {
    file.read(reinterpret_cast<char*>(&header), sizeof(FileHeader));
    if (!file.good()) {
        std::cerr << "Failed to read header\n";
        return false;
    }
    if (header.magic != VALID_MAGIC) {
        std::cerr << "Invalid magic number\n";
        return false;
    }
    if (header.data_size == 0 || header.data_size > 1024 * 1024) {
        std::cerr << "Invalid data size\n";
        return false;
    }
    return true;
}

// 跨函数：读取数据块（含边界检查）
bool readDataBlock(std::ifstream& file, const FileHeader& header, std::vector<char>& buffer) {
    buffer.resize(header.data_size);
    file.read(buffer.data(), header.data_size);
    if (!file.good()) {
        std::cerr << "Failed to read data block\n";
        return false;
    }
    // 防御：验证实际读取字节数
    std::streamsize bytesRead = file.gcount();
    if (bytesRead != header.data_size) {
        std::cerr << "Data size mismatch: expected " << header.data_size 
                  << ", got " << bytesRead << "\n";
        return false;
    }
    return true;
}

// 主处理函数：从文件加载数据并提取前N个字节
bool loadFileData(const std::string& filename, std::vector<char>& output, size_t extract_len) {
    std::ifstream file(filename, std::ios::binary);
    if (!file.is_open()) {
        std::cerr << "Cannot open file\n";
        return false;
    }

    FileHeader header;
    if (!parseHeader(file, header)) {
        return false;
    }

    std::vector<char> data;
    if (!readDataBlock(file, header, data)) {
        return false;
    }

    // 防御：确保 extract_len 不超过数据实际大小
    if (extract_len > data.size()) {
        std::cerr << "Extract length exceeds data size\n";
        return false;
    }

    // 安全提取：仅复制 extract_len 个字节
    output.assign(data.begin(), data.begin() + extract_len);
    return true;
}

