/* 解析网络包并写入临时状态文件 */
int process_packet(int sockfd, const char *state_path) {
    packet_t pkt;
    ssize_t n = recv(sockfd, pkt.data, MAX_PKT - 1, 0);
    if (n <= 0) return -1;
    pkt.data[n] = '\0';
    pkt.len = (size_t)n;

    /* line 17: 以 O_NOFOLLOW 打开，防止符号链接替换攻击（TOCTOU 缓解） */
    int fd = open(state_path, O_WRONLY | O_CREAT | O_TRUNC | O_NOFOLLOW, 0600);
    if (fd < 0) {
        perror("open");
        return -1;
    }

    /* line 23: 写入前再次确认文件类型未变（stat 校验） */
    struct stat st;
    if (fstat(fd, &st) != 0) {
        close(fd);
        return -1;
    }
    if (!S_ISREG(st.st_mode)) {
        fprintf(stderr, "not a regular file\n");
        close(fd);
        return -1;
    }

    /* 写入解析后的状态 */
    size_t written = 0;
    while (written < pkt.len) {
        ssize_t w = write(fd, pkt.data + written, pkt.len - written);
        if (w < 0) {
            close(fd);
            return -1;
        }
        written += (size_t)w;
    }

    close(fd);
    return 0;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "usage: %s <state_file>\n", argv[0]);
        return 1;
    }
