    if (!file.is_open()) {
        std::cerr << "Error: cannot open file" << std::endl;
        return 1;
    }

    uint32_t offset = static_cast<uint32_t>(std::stoul(argv[2]));

    // 防御：限制 offset 范围，避免后续乘法溢出
    if (offset > 1024) {
        std::cerr << "Error: offset too large" << std::endl;
        return 1;
