// 跨函数：解码器将帧数据映射到 DMA 缓冲区
static bool map_frame_to_dma(std::shared_ptr<FrameBuffer> fb, uint8_t** dma_ptr) {
    if (!fb || !dma_ptr || fb->size == 0) {
        return false;  // 防御：空指针/零长度检查
    }
    *dma_ptr = fb->data;
    fb->is_mapped = true;
    return true;
