        return false;
    }

    auto fb = std::make_shared<FrameBuffer>(frame_size);
    uint8_t* dma_ptr = nullptr;

    // 跨函数调用：映射帧到 DMA
    if (!map_frame_to_dma(fb, &dma_ptr)) {
