class RingBuffer {
public:
    explicit RingBuffer(size_t capacity) 
        : buffer_(capacity), capacity_(capacity), write_pos_(0), read_pos_(0) {}

    // Producer: writes data to buffer
    bool push(uint32_t value) {
        size_t current_write = write_pos_.load(std::memory_order_relaxed);
        size_t current_read = read_pos_.load(std::memory_order_acquire);

        // Check if buffer is full
        if ((current_write + 1) % capacity_ == current_read) {
            return false;  // Full
        }

        buffer_[current_write] = value;
        write_pos_.store((current_write + 1) % capacity_, std::memory_order_release);
        return true;
    }

    // Consumer: reads data from buffer
    bool pop(uint32_t& value) {
        size_t current_read = read_pos_.load(std::memory_order_relaxed);
        size_t current_write = write_pos_.load(std::memory_order_acquire);

        // Check if buffer is empty
        if (current_read == current_write) {
            return false;  // Empty
        }

        value = buffer_[current_read];
        read_pos_.store((current_read + 1) % capacity_, std::memory_order_release);
        return true;
    }

private:
    std::vector<uint32_t> buffer_;
    size_t capacity_;
    std::atomic<size_t> write_pos_;
    std::atomic<size_t> read_pos_;
