class SharedCounter {
private:
    std::atomic<uint32_t> counter{0};
    static constexpr uint32_t MAX_VALUE = 1000000;

public:
    // Thread-safe increment with saturation
    bool safe_increment(uint32_t delta) {
        uint32_t current = counter.load(std::memory_order_relaxed);
        while (true) {
            if (current > MAX_VALUE - delta) {
                return false;  // Saturation: prevents overflow
            }
            uint32_t next = current + delta;
            if (counter.compare_exchange_weak(
                    current, next, std::memory_order_relaxed)) {
                return true;
            }
            // current is updated by CAS on failure; loop retries
        }
    }

    uint32_t get_value() const {
        return counter.load(std::memory_order_acquire);
    }
};

// Worker: attempts to add a fixed delta
void worker(SharedCounter& sc, uint32_t delta, int iterations) {
    for (int i = 0; i < iterations; ++i) {
        sc.safe_increment(delta);
    }
}

int main() {
    SharedCounter sc;
    std::vector<std::thread> threads;
    const uint32_t delta = 500000;  // Large delta to stress boundary

    // Spawn 4 threads, each tries 3 increments (total 12 attempts)
    for (int t = 0; t < 4; ++t) {
        threads.emplace_back(worker, std::ref(sc), delta, 3);
    }
    for (auto& th : threads) {
        th.join();
    }

    // Final value must be <= MAX_VALUE (never wrapped)
    uint32_t final_val = sc.get_value();
    return (final_val <= SharedCounter::MAX_VALUE) ? 0 : 1;
