    uint16_t type;
    uint16_t len;
    uint8_t  payload[MAX_PKT_LEN];
} packet_t;

/* Parse a raw packet from the wire into a packet_t.
 * Returns 0 on success, -1 on malformed input. */
static int parse_packet(const uint8_t *raw, size_t raw_len, packet_t *out) {
    if (raw_len < MAX_HDR_LEN) {
        return -1;  /* too short for header */
    }

    /* Copy header fields (big-endian) */
    out->type = (uint16_t)((raw[0] << 8) | raw[1]);
    out->len  = (uint16_t)((raw[2] << 8) | raw[3]);

    /* Validate declared payload length against actual remaining bytes */
    if (out->len > MAX_PKT_LEN) {
        return -1;  /* declared length exceeds buffer capacity */
    }
    if ((size_t)out->len > raw_len - MAX_HDR_LEN) {
        return -1;  /* not enough bytes in the raw buffer */
    }

    /* Copy payload with a strict bound check */
    memcpy(out->payload, raw + MAX_HDR_LEN, out->len);
    return 0;
}

