static int handle_command(const uint8_t *raw, size_t raw_len, char *cmd_buf, size_t cmd_cap) {
    packet_t pkt;
    if (parse_packet(raw, raw_len, &pkt) != 0) {
        return -1;
    }

    /* Command is the first 8 bytes of payload, NUL-terminated */
    if (pkt.len < 8) {
        return -1;
    }

    /* Bounds-checked copy into the caller's buffer */
    if (8 >= cmd_cap) {
        return -1;
    }
    memcpy(cmd_buf, pkt.payload, 8);
    cmd_buf[8] = '\0';
    return 0;
}

