    if (!chunk.data) {
        fclose(fp);
        return false;
    }

    size_t bytes_read = fread(chunk.data, 1, file_size, fp);
    fclose(fp);

    if (bytes_read != (size_t)file_size) {
        SAFE_FREE(chunk.data);
        return false;
    }

    chunk.data[bytes_read] = '\0';
    chunk.size = bytes_read;
    chunk.valid = true;
    return true;
