bool extractMacroblockRow(const uint8_t* src, size_t srcSize, size_t offset,
                          uint8_t* dst, size_t dstCapacity, size_t rowBytes) {
    if (offset > srcSize || rowBytes > dstCapacity) {
        return false; // 边界检查：防止越界读/写
    }
    if (rowBytes > srcSize - offset) {
        return false; // 确保源数据足够
    }
    memcpy(dst, src + offset, rowBytes);
    return true;
}

