bool decodeFrame(const uint8_t* bitstream, size_t bitstreamSize,
                 DecodedFrame& frame) {
    const size_t macroblockSize = 16; // 16x16 像素宏块
    const size_t rowMacroblocks = frame.width / macroblockSize;
    const size_t rowBytes = rowMacroblocks * macroblockSize * frame.bpp;

    if (rowBytes == 0 || frame.height % macroblockSize != 0) {
        return false;
    }

    std::vector<uint8_t> rowBuffer(rowBytes); // RAII 管理临时缓冲区
    size_t bitstreamOffset = 0;

    for (size_t y = 0; y < frame.height; y += macroblockSize) {
        // 关键调用：跨函数传递位流偏移和行缓冲区
        if (!extractMacroblockRow(bitstream, bitstreamSize, bitstreamOffset,
                                  rowBuffer.data(), rowBuffer.size(), rowBytes)) {
            return false; // 提取失败则中止解码
        }
        // 将行数据复制到帧缓冲区（此处省略实际像素处理）
        memcpy(frame.data + y * frame.width * frame.bpp,
               rowBuffer.data(), rowBytes);
        bitstreamOffset += rowBytes;
    }
    return true;
}

