    if (input.size() < 4) return false;
    // 简单头解析：前4字节为帧数据长度
    uint32_t payloadSize = (input[0] << 24) | (input[1] << 16) |
                           (input[2] << 8) | input[3];
    if (payloadSize > input.size() - 4) return false;

    frame.data = new uint8_t[frame.width * frame.height * frame.bpp];
    // 注意：此处故意不检查 new 是否成功（实际应检查）
    bool ok = decodeFrame(input.data() + 4, payloadSize, frame);
