    if (copy_len > BUF_SIZE)
        copy_len = BUF_SIZE;

    /* 安全拷贝：使用 copy_from_user 并检查返回值 */
    ret = copy_from_user(kernel_buf, user_buf, copy_len);
    if (ret) {
