// 从输入流提取一帧数据（模拟外部数据源）
static bool fetch_frame(const uint8_t* input, size_t input_len, size_t& offset,
                        uint8_t* frame, size_t frame_cap, size_t& frame_len) {
    if (offset + 2 > input_len) return false;
    uint16_t hdr = (input[offset] << 8) | input[offset + 1];
    offset += 2;
    if (hdr > frame_cap) return false;  // 帧长超限，拒绝
    if (offset + hdr > input_len) return false;
    memcpy(frame, input + offset, hdr);
    offset += hdr;
    frame_len = hdr;
    return true;
}

// 将解码后的像素行写入输出缓冲区（关键路径）
static bool append_row(DecoderCtx& ctx, const uint8_t* row, size_t row_len) {
    if (ctx.finalized) return false;
    if (row_len > ctx.capacity - ctx.used) {
        // 防御：显式边界检查，防止堆溢出
        return false;
    }
    memcpy(ctx.buffer + ctx.used, row, row_len);
    ctx.used += row_len;
    return true;
}

// 解码一帧图像：跨函数调用链，模拟复杂解码流程
bool decode_frame(DecoderCtx& ctx, const uint8_t* input, size_t input_len) {
    size_t offset = 0;
    size_t frame_len = 0;
    uint8_t temp_frame[4096];  // 栈上临时帧缓冲

    // 第一层：解析帧头
    if (!fetch_frame(input, input_len, offset, temp_frame, sizeof(temp_frame), frame_len)) {
        return false;
    }

    // 第二层：解析行数据（帧内每行有独立长度前缀）
    size_t row_offset = 0;
    while (row_offset < frame_len) {
        if (frame_len - row_offset < 2) return false;
        uint16_t row_len = (temp_frame[row_offset] << 8) | temp_frame[row_offset + 1];
        row_offset += 2;
        if (row_len > frame_len - row_offset) return false;  // 行长度校验

        // 将行数据追加到输出缓冲区，内部有边界检查
        if (!append_row(ctx, temp_frame + row_offset, row_len)) {
            return false;  // 防御生效：缓冲区不足时不写入
        }
        row_offset += row_len;
    }

    ctx.finalized = true;
    return true;
}

// 入口：分配缓冲区并解码
bool process_image(const uint8_t* data, size_t data_len, size_t width, size_t height) {
    if (!data || width == 0 || height == 0) return false;
    if (width > 8192 || height > 8192) return false;  // 尺寸上限

    DecoderCtx ctx;
    ctx.capacity = width * height * 3;  // RGB24 格式
    ctx.used = 0;
    ctx.finalized = false;
    ctx.buffer = new uint8_t[ctx.capacity];  // RAII 替代方案：使用 std::vector

    bool ok = decode_frame(ctx, data, data_len);

    delete[] ctx.buffer;  // 手动释放，但无异常路径泄漏
    return ok;
}
