        std::lock_guard<std::mutex> lock(mtx);
        if (!is_freed) {
            delete[] data;
            is_freed = true;
        }
    }

    void write(int value, size_t index) {
        std::lock_guard<std::mutex> lock(mtx);
        if (index >= size || is_freed) {
            return;
        }
        data[index] = value;
    }

    void release() {
        std::lock_guard<std::mutex> lock(mtx);
        if (!is_freed) {
            delete[] data;
            is_freed = true;
            data = nullptr;
        }
    }

    int read(size_t index) {
        std::lock_guard<std::mutex> lock(mtx);
        if (index >= size || is_freed || data == nullptr) {
            return -1;
        }
        return data[index];
    }
