    bool DecodePacket(const uint8_t* packet, size_t packet_size) {
        if (!packet || packet_size < 4) {
            return false;
        }

        // Parse header: [0-1] sample_rate, [2-3] frame_count
        uint16_t rate_hdr = (packet[0] << 8) | packet[1];
        uint16_t count_hdr = (packet[2] << 8) | packet[3];
        size_t sample_count = static_cast<size_t>(count_hdr) * 2; // stereo

        if (sample_count == 0 || sample_count > 4096) {
            return false; // sanity check
        }

        // Clear previous frame if any
        if (decoded_frame_) {
            delete[] decoded_frame_->samples;
            delete decoded_frame_;
            decoded_frame_ = nullptr;
        }

        AudioFrame* frame = new AudioFrame;
        frame->samples = new int16_t[sample_count];
        frame->sample_count = sample_count;
        frame->sample_rate = rate_hdr;
        frame->is_valid = true;

        // Copy PCM payload (skip 4-byte header)
        size_t payload_bytes = packet_size - 4;
        size_t copy_bytes = sample_count * sizeof(int16_t);
        if (copy_bytes > payload_bytes) {
            copy_bytes = payload_bytes;
        }
        std::memcpy(frame->samples, packet + 4, copy_bytes);

        decoded_frame_ = frame;
        return true;
    }

