class RingBuffer {
public:
    explicit RingBuffer(size_t capacity) 
        : capacity_(capacity), read_pos_(0), write_pos_(0), data_(capacity) {}

    bool push(const uint8_t* bytes, size_t len) {
        if (len > capacity_ - (write_pos_ - read_pos_)) {
            return false;
        }
        std::lock_guard<std::mutex> lock(mutex_);
        for (size_t i = 0; i < len; ++i) {
            data_[(write_pos_ + i) % capacity_] = bytes[i];
        }
        write_pos_ += len;
        return true;
    }

    size_t pop(uint8_t* out, size_t max_len) {
        std::lock_guard<std::mutex> lock(mutex_);
        size_t available = write_pos_ - read_pos_;
        if (available == 0 || max_len == 0) {
            return 0;
        }
        size_t to_read = (max_len < available) ? max_len : available;
        for (size_t i = 0; i < to_read; ++i) {
            out[i] = data_[(read_pos_ + i) % capacity_];
        }
        read_pos_ += to_read;
        return to_read;
    }

    size_t size() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return write_pos_ - read_pos_;
    }

private:
    const size_t capacity_;
    size_t read_pos_;
    size_t write_pos_;
    std::vector<uint8_t> data_;
    mutable std::mutex mutex_;
};

// 跨线程安全消费：调用方保证 out 缓冲区至少 max_len 大
bool consume_all(RingBuffer& rb, uint8_t* out, size_t max_len) {
    size_t total = rb.size();
    if (total > max_len) {
        return false; // 调用方缓冲区不足，拒绝读取
    }
    size_t got = rb.pop(out, max_len);
    return got == total;
}

