    uint8_t in_data[32];
    std::memset(in_data, 0xAB, sizeof(in_data));
    rb.push(in_data, sizeof(in_data));

    uint8_t out_data[64]; // 实际容量 64，但只消费 32 字节
    if (!consume_all(rb, out_data, sizeof(out_data))) {
