    std::mutex mtx_;
    std::atomic<uint64_t> total_ops_{0};
    std::vector<uint32_t> per_thread_counts_;

public:
    explicit SharedCounter(size_t thread_count) : per_thread_counts_(thread_count, 0) {}

    // Thread-safe increment with bound check before accumulation
    bool increment(size_t thread_id, uint32_t delta) {
        if (thread_id >= per_thread_counts_.size()) {
            return false;  // invalid thread id, reject early
        }
        if (delta == 0) {
            return true;  // no-op, avoid unnecessary lock
        }

        std::lock_guard<std::mutex> lock(mtx_);

        // Check for overflow before doing the actual addition
        uint32_t current = per_thread_counts_[thread_id];
        if (current > UINT32_MAX - delta) {
            return false;  // would overflow, reject
        }
        per_thread_counts_[thread_id] = current + delta;

        // total_ops_ is atomic, but we still need to prevent uint64_t overflow
        uint64_t current_total = total_ops_.load(std::memory_order_relaxed);
        if (current_total > UINT64_MAX - delta) {
            // rollback the per-thread update to keep consistency
            per_thread_counts_[thread_id] = current;
            return false;
        }
        total_ops_.store(current_total + delta, std::memory_order_relaxed);
        return true;
    }

    uint64_t get_total() const {
        return total_ops_.load(std::memory_order_relaxed);
