class FrameBuffer {
public:
    FrameBuffer() : data_(nullptr), size_(0), ref_count_(1) {}
    ~FrameBuffer() { Release(); }

    bool Allocate(size_t size) {
        if (data_) return false; // 已分配
        data_ = new uint8_t[size];
        size_ = size;
        return true;
    }

    void AddRef() { ref_count_++; }

    void Release() {
        if (ref_count_ > 1) {
            ref_count_--;
            return;
        }
        delete[] data_;
        data_ = nullptr;
        size_ = 0;
        ref_count_ = 0;
    }

    uint8_t* GetData() const { return data_; }
    size_t GetSize() const { return size_; }

private:
    uint8_t* data_;
    size_t size_;
    int ref_count_;
};

// 解码器核心：解析NAL单元并分发到不同处理函数
static bool ProcessSlice(FrameBuffer* frame, const uint8_t* payload, size_t len) {
    // 模拟切片数据拷贝到帧缓冲区
    if (!frame || !payload || len == 0) return false;
    if (frame->GetSize() < len) return false; // 边界检查

    uint8_t* dst = frame->GetData();
    std::memcpy(dst, payload, len);
    return true;
}

