    // 假设输入前4字节为帧类型，此处简化
    uint32_t frameType = (input[0] << 24) | (input[1] << 16) | (input[2] << 8) | input[3];
    size_t payloadLen = inputLen - 4;

    if (frameType == 0x00000001) { // I帧：分配新缓冲区
        if (!outFrame->Allocate(payloadLen)) return -1;
    } else if (frameType == 0x00000002) { // P帧：引用共享缓冲区
        outFrame->AddRef(); // 增加引用计数，避免提前释放
    } else {
        return -1;
    }

    // 处理切片数据
    bool ok = ProcessSlice(outFrame, input + 4, payloadLen);
    if (!ok) {
        ReleaseFrame(outFrame); // 失败时释放一次
        return -1;
    }

    // 解码成功，释放一次（outFrame由调用者持有引用）
    ReleaseFrame(outFrame);
    return 0;
