    int16_t getSample(size_t channel, size_t sample_idx) const {
        // 通道数固定为 2 (stereo)，每个采样点 2 字节
        size_t offset = (channel * 2 + sample_idx) * 2;

        // 边界检查：确保 offset + 2 不超出缓冲区
        if (offset + 2 > size_) {
            throw std::out_of_range("sample out of range");
        }

        // 手动读取 16-bit little-endian
        return static_cast<int16_t>(
            (data_[offset] & 0xFF) | 
            (static_cast<uint16_t>(data_[offset + 1]) << 8)
        );
    }

private:
    const uint8_t* data_;
    size_t size_;
};

// 模拟从网络流中读取音频帧并解析
bool parseAudioStream(const std::vector<uint8_t>& raw, 
                      size_t frame_start, 
                      size_t frame_len,
                      int16_t& out_sample) {
