        return false;  // 帧边界不合法
    }

    AudioFrame frame(raw.data() + frame_start, frame_len);

    // 尝试读取第 1 通道的第 100 个采样点
    try {
        out_sample = frame.getSample(1, 100);
        return true;
    } catch (const std::out_of_range&) {
        return false;
    }
