private:
    std::vector<uint8_t> buffer_;
    size_t offset_ = 0;
    size_t valid_size_ = 0;
    bool is_open_ = false;

public:
    bool open(const std::string& path) {
        std::ifstream file(path, std::ios::binary);
        if (!file.is_open()) return false;
        file.seekg(0, std::ios::end);
        std::streamsize size = file.tellg();
        if (size <= 0) return false;
        buffer_.resize(static_cast<size_t>(size));
        file.seekg(0, std::ios::beg);
        file.read(reinterpret_cast<char*>(buffer_.data()), size);
        valid_size_ = static_cast<size_t>(size);
        offset_ = 0;
        is_open_ = true;
        return true;
    }

    bool readChunk(uint8_t* out, size_t chunk_size, size_t chunk_index) {
        if (!is_open_) return false;
        // 防御：跨函数计算偏移并验证边界
        size_t start = chunk_index * chunk_size;
        if (chunk_size == 0 || start > valid_size_) return false;
        if (chunk_size > valid_size_ - start) return false;  // 关键边界检查
        size_t end = start + chunk_size;
        if (end > valid_size_) return false;  // 冗余但防御性更强
        std::memcpy(out, buffer_.data() + start, chunk_size);
        offset_ = end;
        return true;
    }

    size_t getValidSize() const { return valid_size_; }
    void close() { buffer_.clear(); valid_size_ = 0; offset_ = 0; is_open_ = false; }
};

int main(int argc, char* argv[]) {
