#define MAX_FILE_SIZE (1 << 20)  // 1 MB limit

// Simulates reading a user-controlled offset from a config file
int64_t get_user_offset(const char* path) {
    FILE* fp = fopen(path, "r");
    if (!fp) return 0;

    char buf[64];
    if (!fgets(buf, sizeof(buf), fp)) {
        fclose(fp);
        return 0;
    }
    fclose(fp);
    return strtoll(buf, nullptr, 10);
}

// Writes a small block at a given offset within a file
int write_block_at_offset(const char* filepath, int64_t offset, const char* data, size_t len) {
    // Defensive: reject negative or absurdly large offsets before any arithmetic
    if (offset < 0 || offset > MAX_FILE_SIZE) {
        fprintf(stderr, "Invalid offset: %lld\n", (long long)offset);
        return -1;
    }

    // Bounds check: ensure offset + len won't exceed the limit
    // (len is size_t, offset is int64_t; cast carefully to avoid overflow)
    if (len > (size_t)(MAX_FILE_SIZE - offset)) {
        fprintf(stderr, "Write would exceed max file size\n");
        return -1;
    }

    int fd = open(filepath, O_WRONLY | O_CREAT, 0644);
    if (fd < 0) return -1;

    // Seek to the offset (safe now due to checks above)
    if (lseek(fd, offset, SEEK_SET) < 0) {
        close(fd);
        return -1;
    }

    ssize_t written = write(fd, data, len);
    close(fd);

    return (written == (ssize_t)len) ? 0 : -1;
}

int main(int argc, char* argv[]) {
    if (argc < 4) {
        fprintf(stderr, "Usage: %s <config> <output_file> <data>\n", argv[0]);
        return 1;
    }

    int64_t user_offset = get_user_offset(argv[1]);
    size_t data_len = strlen(argv[3]);

    // Final validation: data_len must be reasonable
    if (data_len > 512) {
        fprintf(stderr, "Data too large\n");
        return 1;
    }

    // The defensive checks in write_block_at_offset protect against integer overflow
    // when computing offset + len internally.
    if (write_block_at_offset(argv[2], user_offset, argv[3], data_len) != 0) {
        fprintf(stderr, "Write failed\n");
        return 1;
    }

    printf("Write succeeded at offset %lld\n", (long long)user_offset);
    return 0;
