class FrameDecoder {
public:
    FrameDecoder() : frame_{nullptr, 0, 0, 0, false} {}

    ~FrameDecoder() {
        ReleaseFrame();
    }

    // 禁止拷贝（RAII 语义）
    FrameDecoder(const FrameDecoder&) = delete;
    FrameDecoder& operator=(const FrameDecoder&) = delete;

    // 解码入口：跨函数调用链
    bool Decode(const CompressedChunk& input) {
        if (!input.payload || input.len < 4) {
            return false;
        }

        // 解析头部：前2字节为宽度，后2字节为高度
        uint16_t w = (input.payload[0] << 8) | input.payload[1];
        uint16_t h = (input.payload[2] << 8) | input.payload[3];

        return AllocateAndDecode(w, h, input.payload + 4, input.len - 4);
    }

    // 获取解码后的帧（仅用于只读访问）
    const DecodedFrame* GetFrame() const {
        return &frame_;
    }

private:
    DecodedFrame frame_;

    void ReleaseFrame() {
        if (frame_.data) {
            free(frame_.data);
            frame_.data = nullptr;  // 防御：释放后置 NULL
        }
        frame_.size = 0;
        frame_.valid = false;
    }

    bool AllocateAndDecode(uint16_t width, uint16_t height,
                           const uint8_t* compressed, size_t compLen) {
        // 边界检查：防止整数溢出（宽度*高度*3 可能溢出 size_t）
        if (width == 0 || height == 0 || width > 4096 || height > 4096) {
            return false;
        }
        size_t required = static_cast<size_t>(width) * height * 3;
        if (required > 64 * 1024 * 1024) {  // 限制最大 64MB 帧
            return false;
        }

        // 释放旧帧（若有），避免泄漏
        ReleaseFrame();

        uint8_t* buf = static_cast<uint8_t*>(malloc(required));
        if (!buf) {
            return false;
        }

        // 模拟解码：将压缩数据直接拷贝（实际解码器会做复杂变换）
        if (compLen < required) {
            free(buf);
            return false;  // 数据不足，不进入后续流程
        }
        memcpy(buf, compressed, required);

        // 填充帧信息
        frame_.data = buf;
        frame_.size = required;
        frame_.width = width;
        frame_.height = height;
        frame_.valid = true;
        return true;
    }
};

