int ProcessStream(FrameDecoder& decoder, const std::vector<CompressedChunk>& chunks) {
    int decodedCount = 0;
    for (size_t i = 0; i < chunks.size(); ++i) {
        bool ok = decoder.Decode(chunks[i]);
        if (ok) {
            const DecodedFrame* f = decoder.GetFrame();
            if (f && f->valid && f->data) {
