class RowDecoder {
public:
    // 解码单行像素，输出到 dst，输出缓冲区大小由 dstCapacity 指定（单位：字节）
    bool decodeRow(const uint8_t* src, size_t srcLen,
                   uint8_t* dst, size_t dstCapacity) {
        // 输入格式：每像素 2 字节，大端序；行宽由外部 header 解析得到
        if (srcLen < m_width * 2) {
            return false; // 输入不足，防御性检查
        }

        // 目标缓冲区必须容纳 m_width * 2 字节
        if (dstCapacity < m_width * 2) {
            return false; // 输出空间不足，防御性检查
        }

        // 逐像素拷贝并转换字节序（大端 -> 小端）
        for (size_t i = 0; i < m_width; ++i) {
            uint16_t pixel = (static_cast<uint16_t>(src[i * 2]) << 8) |
                             static_cast<uint16_t>(src[i * 2 + 1]);
            // 简单亮度调整（模拟解码后处理）
            pixel = static_cast<uint16_t>(pixel / 2);
            dst[i * 2]     = static_cast<uint8_t>(pixel & 0xFF);
            dst[i * 2 + 1] = static_cast<uint8_t>(pixel >> 8);
        }
        return true;
    }

    void setWidth(size_t width) { m_width = width; }
    size_t getWidth() const { return m_width; }

private:
    size_t m_width = 0; // 行宽（像素数），由外部元数据设置
};

