class ImageDecoder {
public:
    bool decode(const std::vector<uint8_t>& input,
                std::vector<uint8_t>& output) {
        if (input.size() < 4) return false;

        // 假设 header 前 4 字节为行宽（小端）
        size_t width = static_cast<size_t>(input[0]) |
                       (static_cast<size_t>(input[1]) << 8) |
                       (static_cast<size_t>(input[2]) << 16) |
                       (static_cast<size_t>(input[3]) << 24);

        // 宽度合法性验证：防止后续乘法溢出（CWE-190 防护）
        if (width > 65535) return false; // 最大 65535 像素，避免过宽

        RowDecoder rowDecoder;
        rowDecoder.setWidth(width);
        size_t rowBytes = width * 2; // 每行字节数

        // 输入必须包含至少一行数据（header 4 字节 + 行数据）
        if (input.size() < 4 + rowBytes) return false;

        // 分配输出缓冲区
        output.resize(rowBytes);

        // 解码第一行（本例仅演示单行解码）
        bool ok = rowDecoder.decodeRow(input.data() + 4, input.size() - 4,
                                       output.data(), output.size());
        return ok;
    }
};
