bool loadFileHeader(const std::string& path, std::vector<uint8_t>& data) {
    std::ifstream file(path, std::ios::binary);
    if (!file.is_open()) {
        return false;
    }

    // Read entire file into a vector
    file.seekg(0, std::ios::end);
    std::streamsize size = file.tellg();
    if (size <= 0) {
        return false;
    }
    file.seekg(0, std::ios::beg);

    data.resize(static_cast<size_t>(size));
    if (!file.read(reinterpret_cast<char*>(data.data()), size)) {
        data.clear();
        return false;
    }
    return true;
}

bool parseHeader(const std::vector<uint8_t>& data, FileHeader& header) {
    // Minimal file size check: header is 8 bytes (4 + 2 + 2)
    if (data.size() < sizeof(FileHeader)) {
        return false;
    }

    // Use memcpy to avoid alignment issues
    std::memcpy(&header.magic, data.data(), 4);
    std::memcpy(&header.version, data.data() + 4, 2);
    std::memcpy(&header.entry_count, data.data() + 6, 2);

    // Defensive check: entry_count must be within reasonable bounds
    if (header.entry_count > 1000) {
        return false;
    }
    return true;
