                    const std::vector<uint8_t>& src) {
        if (x >= width || y >= height) return false;
        if (blockW == 0 || blockH == 0) return false;
        // 检查块是否超出边界
        if (x + blockW > width || y + blockH > height) return false;

        // 计算目标行偏移（每行固定rowSize字节）
        uint64_t dstOffset = (uint64_t)y * rowSize + (uint64_t)x * 4;
        // 源数据按紧凑格式排列（每行blockW*4字节）
        for (uint32_t row = 0; row < blockH; ++row) {
