        return false;
    }
    file.seekg(0, std::ios::end);
    std::streamoff fileSize = file.tellg();
    file.seekg(0, std::ios::beg);
    if (fileSize <= 0) return false;

    chunk.allocate(static_cast<uint32_t>(fileSize));
    return chunk.readFrom(file);
}

