// 模拟图像解码器：解析 RLE 压缩的像素行数据
// 输入格式: [width(2B)][height(2B)][rle_data...]
// RLE 单元: [count(1B)][pixel_value(1B)]

class RLEDecoder {
public:
    // 解码入口：跨函数调用链 decodeFrame → decodeLine
    std::vector<uint8_t> decodeFrame(const uint8_t* input, size_t inputSize) {
        if (inputSize < 4) throw std::runtime_error("header too small");

        uint16_t width = (input[0] << 8) | input[1];
        uint16_t height = (input[2] << 8) | input[3];

        // 防御：拒绝过大的尺寸声明，防止后续堆分配被恶意撑爆
        if (width == 0 || height == 0 || width > 4096 || height > 4096) {
            throw std::runtime_error("invalid dimensions");
        }

        std::vector<uint8_t> output(static_cast<size_t>(width) * height);
        size_t offset = 4;  // 跳过头部

        for (uint16_t y = 0; y < height; ++y) {
            offset = decodeLine(input, inputSize, offset, output.data() + static_cast<size_t>(y) * width, width);
        }
        return output;
    }

private:
    // 解码单行 RLE 数据到 dst，返回新的 offset
    size_t decodeLine(const uint8_t* input, size_t inputSize, size_t offset,
                      uint8_t* dst, size_t lineWidth) {
        size_t written = 0;

        while (written < lineWidth) {  // 循环条件保证写入不超过 lineWidth
            if (offset + 2 > inputSize) throw std::runtime_error("truncated RLE data");

            uint8_t count = input[offset];
            uint8_t pixel = input[offset + 1];
            offset += 2;

            // 防御：count 若超过剩余空间，则裁剪到剩余空间，避免越界写
            size_t actualCount = count;
            if (actualCount > (lineWidth - written)) {
                actualCount = lineWidth - written;
            }

            // 使用 memset 批量写入，写入量受 actualCount 限制
            std::memset(dst + written, pixel, actualCount);
            written += actualCount;
        }
        return offset;
    }
};

// 使用示例（非漏洞触发路径）
int processFrame(const uint8_t* frameData, size_t frameSize) {
    try {
        RLEDecoder decoder;
        auto pixels = decoder.decodeFrame(frameData, frameSize);
