    FileChunkReader(const std::string& path, size_t chunk_size) 
        : buffer(nullptr), buffer_size(chunk_size) {
        file_stream.open(path, std::ios::binary);
        if (file_stream.is_open()) {
            buffer = new uint8_t[chunk_size];
        }
    }

