        if (!file_stream.is_open() || buffer == nullptr) {
            return false;
        }

        file_stream.read(reinterpret_cast<char*>(buffer), buffer_size);
        std::streamsize bytes_read = file_stream.gcount();

        if (bytes_read <= 0) {
            return false;
        }

        // 防御：检查输出缓冲区大小是否足够容纳读取的数据
        if (output_size < static_cast<size_t>(bytes_read)) {
            std::cerr << "Error: output buffer too small for chunk data" << std::endl;
            return false;
        }

        // 安全复制：使用 memcpy 且已确认 output_size >= bytes_read
        std::memcpy(output, buffer, static_cast<size_t>(bytes_read));
        return true;
    }

    size_t get_buffer_size() const {
        return buffer_size;
    }
};

