{
    size_t avail, to_read;
    int ret;

    if (mutex_lock_interruptible(&rb->lock))
        return -ERESTARTSYS;

    avail = (rb->head >= rb->tail) ? (rb->head - rb->tail) :
            (rb->size - rb->tail + rb->head);

    /* 防御：限制读取长度不超过可用数据及用户请求 */
    to_read = min(count, avail);
    to_read = min(to_read, MAX_READ_SIZE);

    if (to_read == 0) {
        mutex_unlock(&rb->lock);
        return 0;
    }

    /* 防御：检查目标缓冲区长度（此处假设用户已传入有效size） */
