    ret = copy_to_user(buf, rb->data + rb->tail, to_read);
    if (ret) {
        mutex_unlock(&rb->lock);
        return -EFAULT;
    }

    rb->tail = (rb->tail + to_read) % rb->size;
    mutex_unlock(&rb->lock);
    return to_read;
}

