    if (!pkt)
        return -ENOMEM;

    if (copy_from_user(pkt, user_pkt, sizeof(*pkt))) {
        ret = -EFAULT;
        goto out_free;
    }

    if (pkt->len > MAX_BUF_SIZE) {
        ret = -EINVAL;
        goto out_free;
    }

    pkt->payload = kmalloc(pkt->len + 1, GFP_KERNEL);
    if (!pkt->payload) {
        ret = -ENOMEM;
        goto out_free;
    }

    if (copy_from_user(pkt->payload, user_pkt->payload, pkt->len)) {
        ret = -EFAULT;
        goto out_free_payload;
