bool getFileSize(const std::string& filePath, uint32_t& sizeOut) {
    std::ifstream file(filePath, std::ios::binary | std::ios::ate);
    if (!file.is_open()) {
        return false;
    }
    std::streamoff end = file.tellg();
    if (end < 0) {
        return false;
    }
    // 文件大小以流偏移量表示（通常为64位），此处显式检查是否超出uint32_t范围
    if (static_cast<uint64_t>(end) > UINT32_MAX) {
        return false;
    }
    sizeOut = static_cast<uint32_t>(end);
    return true;
}

// 将文件内容读取到缓冲区，缓冲区大小由size参数指定
bool readFileContent(const std::string& filePath, uint32_t size, std::vector<char>& buffer) {
    std::ifstream file(filePath, std::ios::binary);
    if (!file.is_open()) {
        return false;
    }
    buffer.resize(size);
    file.read(buffer.data(), size);
    return file.good() || file.eof();
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        std::cerr << "Usage: " << argv[0] << " <file>" << std::endl;
        return 1;
    }

