    if (!getFileSize(argv[1], fileSize)) {
        std::cerr << "Failed to get file size." << std::endl;
        return 1;
    }

    std::vector<char> fileData;
    if (!readFileContent(argv[1], fileSize, fileData)) {
        std::cerr << "Failed to read file." << std::endl;
