class SharedBuffer {
private:
    std::vector<int> data_;
    std::mutex mtx_;
    std::atomic<bool> ready_{false};
    size_t read_pos_ = 0;

public:
    explicit SharedBuffer(size_t size) : data_(size, 0) {}

    void produce() {
        std::lock_guard<std::mutex> lock(mtx_);
        for (size_t i = 0; i < data_.size(); ++i) {
            data_[i] = static_cast<int>(i * 2);
        }
        ready_.store(true, std::memory_order_release);
    }

    // 消费者：跨线程读取，使用互斥锁保护共享状态
    int consume() {
        std::lock_guard<std::mutex> lock(mtx_);
        if (!ready_.load(std::memory_order_acquire)) {
            return -1;  // 数据未就绪
        }
        if (read_pos_ >= data_.size()) {
            return -1;  // 已读完
        }
        return data_[read_pos_++];  // 安全读取，read_pos_ 受锁保护
    }

    size_t remaining() {
        std::lock_guard<std::mutex> lock(mtx_);
        if (!ready_.load(std::memory_order_acquire)) {
            return 0;
        }
        return data_.size() - read_pos_;
    }
};

void producer_worker(SharedBuffer& buf) {
    std::this_thread::sleep_for(std::chrono::milliseconds(10));
    buf.produce();
}

void consumer_worker(SharedBuffer& buf, std::atomic<int>& total) {
    int val;
    while ((val = buf.consume()) != -1) {
        total.fetch_add(val, std::memory_order_relaxed);
    }
}

