    std::thread t1(producer_worker, std::ref(buffer));
    std::thread t2(consumer_worker, std::ref(buffer));
    std::thread t3(consumer_worker, std::ref(buffer));

    t1.join();
    t2.join();
    t3.join();

    std::cout << "Sum: " << sum.load() << " Remaining: " << buffer.remaining() << std::endl;
    return 0;
