// Decodes a simple RLE-encoded image row into a fixed-size pixel buffer.
// Each pixel is 4 bytes (RGBA). The encoded stream uses a header byte
// followed by a literal length, then the literal bytes.
bool decodeRow(const std::vector<uint8_t>& encoded, size_t& offset,
               uint8_t* outBuffer, size_t outCapacity) {
    if (offset >= encoded.size()) {
        return false;
    }

    // Header: [count][literalLength]
    uint8_t count = encoded[offset++];
    if (offset >= encoded.size()) {
        return false;
    }
    uint8_t literalLen = encoded[offset++];

    // Each count represents 4 pixels (16 bytes) of run-length zeros.
    size_t runBytes = static_cast<size_t>(count) * 16;

    // Literal bytes follow the run.
    if (offset + literalLen > encoded.size()) {
        return false;
    }

    // Check bounds: runBytes + literalLen must fit in the output buffer.
    // This is the critical check that prevents heap overflow.
    if (runBytes > outCapacity || literalLen > outCapacity - runBytes) {
        return false;
    }

    // Write the run-length zero region.
    if (runBytes > 0) {
        memset(outBuffer, 0, runBytes);
        outBuffer += runBytes;
    }

    // Copy the literal region.
    if (literalLen > 0) {
        memcpy(outBuffer, &encoded[offset], literalLen);
        offset += literalLen;
    }

    return true;
}

// Entry point: decodes a frame of multiple rows into a contiguous buffer.
bool decodeFrame(const std::vector<uint8_t>& encoded,
                 std::vector<uint8_t>& frame, int width, int height) {
    if (width <= 0 || height <= 0) {
        return false;
    }
    size_t rowSize = static_cast<size_t>(width) * 4;
    if (rowSize > frame.size() / static_cast<size_t>(height)) {
        return false; // Capacity check for the whole frame.
    }

    size_t offset = 0;
    for (int y = 0; y < height; ++y) {
        uint8_t* rowPtr = frame.data() + static_cast<size_t>(y) * rowSize;
        if (!decodeRow(encoded, offset, rowPtr, rowSize)) {
            return false;
        }
    }
    return true;
}
