        if (ref_count_ == 0) {
            free(data_);
            data_ = nullptr;  // 关键防御：置NULL防止悬垂
            size_ = 0;
        }
    }

    uint8_t* GetData() const { return data_; }
    size_t GetSize() const { return size_; }

private:
    uint8_t* data_;
    size_t size_;
    int ref_count_;
};

// 跨函数解码流程：解码器主入口
bool DecodeFrame(const std::vector<uint8_t>& compressed, 
                 FrameBuffer& output, 
                 FrameBuffer& scratch) {
    // 步骤1：分配输出缓冲区
    if (!output.Allocate(1024 * 1024)) return false;

    // 步骤2：使用scratch作为临时工作区（假设已由调用方分配）
    // 模拟解码过程：将压缩数据复制到scratch，再处理
    if (compressed.size() > scratch.GetSize()) {
        // 输入过大，解码失败
        output.Release();  // 释放输出
        return false;
    }

    // 模拟解码：将压缩数据写入scratch
    memcpy(scratch.GetData(), compressed.data(), compressed.size());

    // 步骤3：将scratch内容转换到output（模拟解码结果）
    memcpy(output.GetData(), scratch.GetData(), compressed.size());

    // 步骤4：清理scratch（模拟临时资源释放）
    scratch.Release();  // 第一次释放

    // 步骤5：解码成功，但scratch的Release由调用方负责
    // 注意：这里没有再次释放scratch，符合设计

    return true;
}

// 调用方：解码一帧并管理资源
bool ProcessFrame(const std::vector<uint8_t>& input) {
    FrameBuffer output;
    FrameBuffer scratch;

    // 分配scratch为工作区
    if (!scratch.Allocate(2 * 1024 * 1024)) return false;

    // 解码帧
    if (!DecodeFrame(input, output, scratch)) {
        scratch.Release();  // 释放scratch
        return false;
    }

    // 使用output进行后续处理（如显示、保存）
    // ...

    // 清理资源
    output.Release();
    scratch.Release();  // 正常释放一次

    return true;
}
