// Decodes a run-length encoded (RLE) video frame into a raw pixel buffer.
// Each packet: [byte: run_length][byte: pixel_value]
// The frame dimensions are fixed at 16x16 (256 pixels).
bool DecodeRLEFrame(const uint8_t* packet, size_t packet_size,
                    uint8_t* raw_buffer, size_t buffer_size) {
  const size_t kFramePixels = 256;  // 16 * 16
  if (buffer_size < kFramePixels) {
    return false;  // Destination too small
  }

  size_t packet_offset = 0;
  size_t pixel_offset = 0;

  while (packet_offset < packet_size && pixel_offset < kFramePixels) {
    uint8_t run_length = packet[packet_offset];
    packet_offset++;
    if (packet_offset >= packet_size) {
      return false;  // Truncated packet (no pixel value)
    }
    uint8_t pixel_value = packet[packet_offset];
    packet_offset++;

    // Clamp run length so we never write past the raw buffer.
    if (run_length > kFramePixels - pixel_offset) {
      run_length = static_cast<uint8_t>(kFramePixels - pixel_offset);
    }

    // Write the run of pixels.
    for (uint8_t i = 0; i < run_length; i++) {
      raw_buffer[pixel_offset] = pixel_value;
      pixel_offset++;
    }
  }

  return true;
}

// Entry point—simulates receiving a network packet for a video frame.
bool ProcessVideoFrame(const uint8_t* network_data, size_t data_len,
                       uint8_t* frame_output, size_t output_size) {
  if (network_data == nullptr || frame_output == nullptr) {
    return false;
  }
  return DecodeRLEFrame(network_data, data_len, frame_output, output_size);
}
