// Decodes a simple 24-bit bitmap-like format into raw RGBA pixels.
// The file header contains width (uint32) and height (uint32).
// Each pixel in the file is 3 bytes (RGB), output is 4 bytes (RGBA).
bool decodeBitmap(const std::string& filepath, std::vector<uint8_t>& outPixels,
                  uint32_t& outWidth, uint32_t& outHeight) {
    std::ifstream file(filepath, std::ios::binary);
    if (!file.is_open()) {
        std::cerr << "Failed to open file\n";
        return false;
    }

    uint32_t width, height;
    file.read(reinterpret_cast<char*>(&width), sizeof(width));
    file.read(reinterpret_cast<char*>(&height), sizeof(height));
    if (!file) {
        std::cerr << "Failed to read header\n";
        return false;
    }

    // Reject absurd dimensions early to avoid huge allocations.
    if (width == 0 || height == 0 || width > 4096 || height > 4096) {
        std::cerr << "Invalid dimensions\n";
        return false;
    }

    // Check for integer overflow: width * height * 4 must fit in size_t.
    // On 32-bit systems, size_t is 32-bit; on 64-bit, it's 64-bit.
    // Since width/height are capped at 4096, product fits easily on 64-bit.
    // But on 32-bit, 4096*4096*4 = 67,108,864 which also fits in 32-bit.
    // However, the pixel buffer size is width * height * 4, and we read
    // width * height * 3 bytes from the file. Both are safe here due to caps.
    const size_t pixelCount = static_cast<size_t>(width) * static_cast<size_t>(height);
    const size_t inputBytes = pixelCount * 3;   // RGB per pixel
    const size_t outputBytes = pixelCount * 4;  // RGBA per pixel

    // The multiplication above is safe because width/height <= 4096.
    // But if the caps were removed, this would overflow on 32-bit.
    // For defense-in-depth, we explicitly check against SIZE_MAX.
    if (pixelCount > SIZE_MAX / 4 || pixelCount > SIZE_MAX / 3) {
        std::cerr << "Overflow detected\n";
        return false;
    }

    outPixels.resize(outputBytes);
    std::vector<uint8_t> fileData(inputBytes);
    file.read(reinterpret_cast<char*>(fileData.data()), inputBytes);
    if (!file) {
        std::cerr << "Failed to read pixel data\n";
        return false;
    }

    // Convert RGB to RGBA (alpha = 255).
    for (size_t i = 0; i < pixelCount; ++i) {
        outPixels[i * 4 + 0] = fileData[i * 3 + 0];
        outPixels[i * 4 + 1] = fileData[i * 3 + 1];
        outPixels[i * 4 + 2] = fileData[i * 3 + 2];
        outPixels[i * 4 + 3] = 255;
    }

    outWidth = width;
    outHeight = height;
    return true;
}
