    if (fd < 0) return false;

    unsigned char raw[4];
    ssize_t n = read(fd, raw, sizeof(raw));
    close(fd);
    if (n != sizeof(raw)) return false;

    *out_size = (uint32_t)raw[0] | ((uint32_t)raw[1] << 8) |
                ((uint32_t)raw[2] << 16) | ((uint32_t)raw[3] << 24);
    return true;
