    if (!read_size_from_file(path, &chunk_size)) {
        fprintf(stderr, "Failed to read size\n");
        return -1;
    }

    // 防御：拒绝超大块，限制为 1MB
    const uint32_t MAX_CHUNK = 1024 * 1024;
    if (chunk_size > MAX_CHUNK) {
        fprintf(stderr, "Chunk too large: %u\n", chunk_size);
        return -1;
    }

    // 分配缓冲区，大小基于文件控制字段
    char* buffer = (char*)malloc(chunk_size + 1);
    if (!buffer) {
        fprintf(stderr, "malloc failed\n");
        return -1;
    }

    // 模拟读取数据（此处省略实际 read 逻辑）
    memset(buffer, 'A', chunk_size);
    buffer[chunk_size] = '\0';  // 确保字符串终止

