    bool readVarInt(uint32_t& out) {
        if (offset >= srcLen) return false;
        uint32_t result = 0;
        uint32_t shift = 0;
        uint8_t byte;
        do {
            if (offset >= srcLen || shift > 28) return false;
            byte = src[offset++];
            result |= (byte & 0x7F) << shift;
            shift += 7;
        } while (byte & 0x80);
        out = result;
        return true;
    }

