    uint32_t runLength = 0;
    uint32_t pixelValue = 0;

    // Read RLE header
    if (!buf.readVarInt(runLength) || !buf.readVarInt(pixelValue))
        return false;

    // Critical: ensure runLength does not exceed rowWidth
    if (runLength > rowWidth)
        return false;

    // Bounds check: verify enough source bytes remain for the run
    if (buf.remaining() < runLength)
        return false;

    // Fill the row with repeated pixel value
    for (uint32_t i = 0; i < runLength; ++i) {
        outRow[i] = static_cast<uint8_t>(pixelValue);
    }
    return true;
}

