/* 将命令加入队列，成功返回0 */
static int queue_push(CommandQueue* q, Command* cmd) {
    if (q->count >= CMD_QUEUE_CAP) return -1;
    q->slots[q->tail] = cmd;
    q->tail = (q->tail + 1) % CMD_QUEUE_CAP;
    q->count++;
    return 0;
}

/* 从队列取出命令，返回命令指针，调用方负责释放 */
static Command* queue_pop(CommandQueue* q) {
    if (q->count == 0) return NULL;
    Command* cmd = q->slots[q->head];
    q->head = (q->head + 1) % CMD_QUEUE_CAP;
    q->count--;
    return cmd;
}

