#include <string>

class FileGuard {
public:
    FileGuard(const char* path) {
        fp = fopen(path, "r");
    }
    ~FileGuard() {
        if (fp) {
            fclose(fp);
        }
    }
    FILE* get() { return fp; }
private:
    FILE* fp;
};

char* read_file_content(const char* path, size_t* out_len) {
    FileGuard guard(path);
    FILE* fp = guard.get();
    if (!fp) {
        return nullptr;
    }

    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    fseek(fp, 0, SEEK_SET);

    if (file_size <= 0) {
        return nullptr;
    }

    char* buffer = (char*)malloc(file_size + 1);
    if (!buffer) {
        return nullptr;
    }

    size_t bytes_read = fread(buffer, 1, file_size, fp);
    buffer[bytes_read] = '\0';
    *out_len = bytes_read;

    // 防御核心：RAII 自动管理 FILE*，无需手动 free，杜绝 double free
    return buffer;
}

int main() {
    size_t len = 0;
    char* data = read_file_content("/tmp/example.txt", &len);
    if (data) {
        printf("Content: %s\n", data);
        free(data);  // 仅释放 buffer，FILE* 由 FileGuard 析构自动关闭
    }
    return 0;
}
