// 跨函数调用：从流中读取定长数据，失败时抛出异常
static void read_exact(const uint8_t*& src, size_t& remaining, uint8_t* dst, size_t len) {
    if (remaining < len) {
        throw std::runtime_error("truncated data");
    }
    std::memcpy(dst, src, len);
    src += len;
    remaining -= len;
}

// 解码单行像素数据，返回该行实际填充的字节数
static size_t decode_row(const uint8_t* row_data, size_t row_bytes,
                         uint8_t* out_row, uint32_t width) {
    // 边界检查：拒绝超过宏限制的行宽
    if (row_bytes > MAX_ROW_BYTES) {
        throw std::runtime_error("row too wide");
    }
    // 每像素 3 字节，计算有效载荷长度
    size_t payload_bytes = width * 3;
    if (payload_bytes > row_bytes) {
        throw std::runtime_error("row data insufficient");
    }
    std::memcpy(out_row, row_data, payload_bytes);
    return payload_bytes;
}

// 主解码入口：解析头部并逐行复制，使用 RAII 管理输出缓冲区
DecodedImage decode_image(const uint8_t* data, size_t size) {
    if (size < 8) {
        throw std::runtime_error("header too small");
    }

    DecodedImage img;
    img.width = static_cast<uint32_t>(data[0]) |
                (static_cast<uint32_t>(data[1]) << 8) |
                (static_cast<uint32_t>(data[2]) << 16) |
                (static_cast<uint32_t>(data[3]) << 24);
    img.height = static_cast<uint32_t>(data[4]) |
                 (static_cast<uint32_t>(data[5]) << 8) |
                 (static_cast<uint32_t>(data[6]) << 16) |
                 (static_cast<uint32_t>(data[7]) << 24);

    // 防御：拒绝超大数据尺寸，防止后续乘法溢出
    if (img.width > MAX_ROW_BYTES / 3 || img.height > 10000) {
        throw std::runtime_error("dimension too large");
    }

    // RAII：vector 自动管理内存，异常时安全释放
    img.pixels.resize(static_cast<size_t>(img.width) * img.height * 3);

    const uint8_t* cursor = data + 8;
    size_t remaining = size - 8;

    // 逐行解码，每行前面有 4 字节长度前缀
    for (uint32_t y = 0; y < img.height; ++y) {
        uint8_t len_buf[4];
        read_exact(cursor, remaining, len_buf, sizeof(len_buf));
        uint32_t row_len = static_cast<uint32_t>(len_buf[0]) |
                           (static_cast<uint32_t>(len_buf[1]) << 8) |
                           (static_cast<uint32_t>(len_buf[2]) << 16) |
                           (static_cast<uint32_t>(len_buf[3]) << 24);

        // 防御：行长度必须介于有效载荷和宏上限之间
        if (row_len < img.width * 3 || row_len > MAX_ROW_BYTES) {
            throw std::runtime_error("invalid row length");
        }
        read_exact(cursor, remaining, const_cast<uint8_t*>(cursor) /* 占位 */, 0); // 仅检查剩余量

        // 解码行数据（row_len 已受宏限制，不会越界读）
        uint8_t* out_row = img.pixels.data() + static_cast<size_t>(y) * img.width * 3;
        size_t written = decode_row(cursor, row_len, out_row, img.width);
        cursor += row_len;
        remaining -= row_len;
        (void)written; // 返回值用于校验，此处忽略
    }

    return img;
}
