public:
    explicit RingBuffer(size_t capacity) : capacity_(capacity), buffer_(capacity) {}

    bool push(const uint8_t* data, size_t len) {
        if (len == 0 || len > capacity_) return false;
        std::lock_guard<std::mutex> lock(mutex_);
        if (count_ + len > capacity_) return false;  // 空间不足
        size_t first_part = std::min(len, capacity_ - write_pos_);
        std::memcpy(&buffer_[write_pos_], data, first_part);
        if (first_part < len) {
            std::memcpy(&buffer_[0], data + first_part, len - first_part);
        }
        write_pos_ = (write_pos_ + len) % capacity_;
        count_ += len;
        return true;
    }

    bool pop(uint8_t* out, size_t len) {
        if (len == 0 || len > capacity_) return false;
        std::lock_guard<std::mutex> lock(mutex_);
        if (count_ < len) return false;  // 数据不足
        size_t first_part = std::min(len, capacity_ - read_pos_);
        std::memcpy(out, &buffer_[read_pos_], first_part);
        if (first_part < len) {
            std::memcpy(out + first_part, &buffer_[0], len - first_part);
        }
        read_pos_ = (read_pos_ + len) % capacity_;
        count_ -= len;
        return true;
    }

    size_t available() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return count_;
    }

private:
    size_t capacity_;
    size_t write_pos_ = 0;
    size_t read_pos_ = 0;
