bool accumulate_chunk_sizes(const std::vector<uint32_t>& chunks, uint64_t& total) {
    total = 0;
    for (auto c : chunks) {
        total += static_cast<uint64_t>(c);  // line 18: 显式提升到 64 位
    }
    return true;
}

// 计算文件所需的缓冲区大小（防御：64 位累加 + 上限检查）
bool compute_buffer_size(const std::string& path, size_t& buf_size) {
    uint32_t header_size = 0;
    if (!read_file_size(path, header_size)) {
        std::cerr << "Failed to read header\n";
        return false;
    }

    // 防御1: 上限检查，拒绝超大 header（防止后续乘法溢出）
    if (header_size > 1024 * 1024) return false;

    std::vector<uint32_t> chunk_sizes;
    chunk_sizes.reserve(header_size);

    // 模拟从文件中读取每个 chunk 大小
    std::ifstream file(path, std::ios::binary);
    for (uint32_t i = 0; i < header_size; ++i) {
        uint32_t sz = 0;
        file.read(reinterpret_cast<char*>(&sz), sizeof(sz));
        if (sz > 1024 * 1024) return false;  // 防御2: 单块大小上限
        chunk_sizes.push_back(sz);
    }

    uint64_t total = 0;
    if (!accumulate_chunk_sizes(chunk_sizes, total)) return false;

    // 防御3: 总大小上限（防止 64 位到 size_t 的隐式转换问题）
    if (total > (1024ULL * 1024 * 1024)) return false;

    buf_size = static_cast<size_t>(total);  // line 47: 安全转换，已确保在 size_t 范围内
    return true;
}

