    std::vector<char> buffer(buf_size);
    if (buffer.empty() && buf_size > 0) return false;

    // 模拟读取文件内容到缓冲区
    std::ifstream file(path, std::ios::binary);
    file.read(buffer.data(), buf_size);
    return file.good() || file.eof();
