        uint32_t required = compressed_size / 2;
        if (required > max_samples) return false;
        for (uint32_t i = 0; i < required; ++i) {
            output[i] = static_cast<int16_t>(compressed[i * 2] | (compressed[i * 2 + 1] << 8));
        }
        return true;
    }

