        frame_pool.resize(pool_size);
        for (uint32_t i = 0; i < pool_size; ++i) {
            frame_pool[i].samples = nullptr;
            frame_pool[i].sample_count = 0;
            frame_pool[i].is_valid = false;
        }
        is_initialized = true;
        return true;
    }

    // 释放帧数据（安全版本：置空指针）
    void release_frame(AudioFrame& frame) {
        if (frame.samples != nullptr) {
            delete[] frame.samples;
            frame.samples = nullptr;  // 防御：置空防止悬垂指针
        }
        frame.sample_count = 0;
        frame.is_valid = false;
    }

