    bool decode_frame(uint32_t frame_index, uint32_t compressed_size) {
        if (!is_initialized || frame_index >= frame_pool.size()) return false;

        AudioFrame& frame = frame_pool[frame_index];
        // 如果帧已有效，先释放旧数据
        if (frame.is_valid) {
            release_frame(frame);
        }

        // 分配样本缓冲区（每 2 字节压缩数据产生 1 个样本，加 1 防止除零）
        uint32_t max_samples = (compressed_size / 2) + 1;
