        if (!read_compressed_data(compressed.data(), compressed_size)) {
            delete[] buffer;
            return false;
        }

        // 解码
        if (!decode_to_pcm(compressed.data(), compressed_size, buffer, max_samples)) {
            delete[] buffer;
            return false;
        }

