        std::vector<char> buffer(chunk_size);
        file_stream.read(buffer.data(), chunk_size);

        size_t bytes_read = file_stream.gcount();
        if (bytes_read <= 0) {
            return false;
        }

        output.assign(buffer.begin(), buffer.begin() + bytes_read);
        return true;
    }

    ~FileChunkReader() {
        if (file_stream.is_open()) {
