// 解码器：从缓冲区中提取像素行，执行简单的 RGB565 到 RGB888 转换
class ImageDecoder {
public:
    // 输入: 压缩的像素数据, 输出: 解码后的 RGB888 行缓冲
    bool DecodeRow(const std::vector<uint8_t>& compressed,
                   uint8_t* out_rgb, size_t out_capacity) {
        // 头部: 2字节表示行内像素数量
        if (compressed.size() < 2) return false;
        uint16_t pixel_count = (compressed[0] << 8) | compressed[1];

        // 每个像素在压缩流中占 2 字节 (RGB565)
        size_t needed = static_cast<size_t>(pixel_count) * 2;
        if (compressed.size() < 2 + needed) return false;  // 输入长度检查

        // 输出: 每像素 3 字节 (RGB888)
        size_t out_needed = static_cast<size_t>(pixel_count) * 3;
        if (out_needed > out_capacity) return false;  // 输出容量检查

        size_t pos = 2;
        for (uint16_t i = 0; i < pixel_count; ++i) {
            uint16_t rgb565 = (compressed[pos] << 8) | compressed[pos + 1];
            pos += 2;

            // RGB565 拆分为 RGB888
            uint8_t r = (rgb565 >> 11) & 0x1F;
            uint8_t g = (rgb565 >> 5) & 0x3F;
            uint8_t b = rgb565 & 0x1F;
            r = (r << 3) | (r >> 2);
            g = (g << 2) | (g >> 4);
            b = (b << 3) | (b >> 2);

            out_rgb[i * 3] = r;
            out_rgb[i * 3 + 1] = g;
            out_rgb[i * 3 + 2] = b;
        }
        return true;
    }
};
