    if (!file.is_open()) {
        return false;
    }

    FileHeader header;
    file.read(reinterpret_cast<char*>(&header), sizeof(FileHeader));
    if (file.gcount() != sizeof(FileHeader)) {
        return false;
    }

    // 校验魔数，防止恶意构造
    if (header.magic != 0xDEADBEEF) {
        return false;
    }

    // 防御：限制 entry_count 避免后续越界读
    if (header.entry_count > 1024) {
        return false;
    }

    // 防御：确保 data_offset 在文件头之后
    if (header.data_offset < sizeof(FileHeader)) {
        return false;
    }

    // 定位到数据区
    file.seekg(header.data_offset, std::ios::beg);
    if (!file.good()) {
        return false;
    }

    // 防御：读取前检查 data_offset 不会越过文件末尾
    file.seekg(0, std::ios::end);
    std::streampos file_size = file.tellg();
    file.seekg(header.data_offset, std::ios::beg);
    if (header.data_offset >= static_cast<uint32_t>(file_size)) {
        return false;
    }

    // 分配输出缓冲区
    output.resize(header.entry_count * 4);

