bool readFileHeader(const std::string& filepath, std::vector<uint8_t>& output) {
    std::ifstream file(filepath, std::ios::binary);
    if (!file.is_open()) {
        std::cerr << "Failed to open file: " << filepath << std::endl;
        return false;
    }

    // Read 4-byte magic number
    uint32_t magic;
    file.read(reinterpret_cast<char*>(&magic), sizeof(magic));
    if (file.gcount() != sizeof(magic)) {
        std::cerr << "Invalid file: too short for magic" << std::endl;
        return false;
    }

    // Read 4-byte size field (LE)
    uint32_t dataSize;
    file.read(reinterpret_cast<char*>(&dataSize), sizeof(dataSize));
    if (file.gcount() != sizeof(dataSize)) {
        std::cerr << "Invalid file: too short for size" << std::endl;
        return false;
    }

    // Validate size: must be <= 1MB to prevent excessive allocation
    const uint32_t MAX_SIZE = 1024 * 1024; // 1MB
    if (dataSize > MAX_SIZE) {
        std::cerr << "Size field too large: " << dataSize << std::endl;
        return false;
    }

    // Allocate buffer with exact size (no integer overflow since dataSize <= 1MB)
    std::vector<uint8_t> buffer(dataSize);
    if (dataSize > 0) {
        file.read(reinterpret_cast<char*>(buffer.data()), dataSize);
        if (file.gcount() != static_cast<std::streamsize>(dataSize)) {
            std::cerr << "File truncated: expected " << dataSize 
                      << " bytes, got " << file.gcount() << std::endl;
            return false;
        }
    }

