        if (len > size) return false;  // 数据不足，拒绝读取
        std::lock_guard<std::mutex> lock(mtx);
        for (size_t i = 0; i < len; ++i) {
            out[i] = data[(head + i) % capacity];
        }
        head = (head + len) % capacity;
        size -= len;
        return true;
    }

