    const size_t input_size = input.size();

    // Sanity check: input must have at least a 2-byte header for total pixel count.
    if (input_size < 2) {
        return false;
    }

    uint16_t total_pixels = (static_cast<uint16_t>(input[0]) << 8) | input[1];
    pos = 2;

    // Bound the output size before allocation to prevent overflow in the loop below.
    // Each pixel is 4 bytes, so we check against SIZE_MAX / 4.
    if (static_cast<size_t>(total_pixels) > output.max_size() / 4) {
        return false;
    }

    output.clear();
    output.reserve(static_cast<size_t>(total_pixels) * 4);

    while (pos < input_size && output.size() < static_cast<size_t>(total_pixels) * 4) {
        if (pos + 2 > input_size) {
            return false; // Incomplete count header
        }
        uint16_t run_count = (static_cast<uint16_t>(input[pos]) << 8) | input[pos + 1];
        pos += 2;

        if (pos + 4 > input_size) {
            return false; // Incomplete pixel data
        }

        // Extract the 4-byte pixel.
        uint8_t pixel[4] = { input[pos], input[pos + 1], input[pos + 2], input[pos + 3] };
        pos += 4;

        // Extend the output by run_count pixels.
        // The outer loop condition (output.size() < total_pixels * 4) ensures we never
        // exceed the pre-allocated buffer size. We also cap the addition here.
        size_t remaining_bytes = static_cast<size_t>(total_pixels) * 4 - output.size();
        size_t bytes_to_add = static_cast<size_t>(run_count) * 4;
        if (bytes_to_add > remaining_bytes) {
            bytes_to_add = remaining_bytes; // Truncate to fit the declared total.
