    file.seekg(0, std::ios::beg);

    // 栈上缓冲区，由调用方传入大小
    char nameBuffer[MAX_NAME_LEN + 1] = {0};
    uint32_t len = parseHeader(file, nameBuffer, sizeof(nameBuffer));

    if (len == 0) {
        return false;
    }

    // 使用名称：此处仅验证读取成功
    std::cout << "Name: " << nameBuffer << " (len=" << len << ")\n";
    return true;
}

int main(int argc, char* argv[]) {
