// Simulated image decoder: parses a simple run-length encoded pixel buffer
// into a fixed-size output frame. Safe version with comprehensive boundary checks.

constexpr size_t FRAME_WIDTH = 64;
constexpr size_t FRAME_HEIGHT = 48;
constexpr size_t FRAME_SIZE = FRAME_WIDTH * FRAME_HEIGHT; // 3072 bytes

struct DecodedFrame {
    uint8_t pixels[FRAME_SIZE];
    size_t size;
};

// RLE format: [count:1 byte][value:1 byte], repeated until input exhausted.
// Output must not exceed FRAME_SIZE bytes.
bool decode_rle(const uint8_t* input, size_t input_len, DecodedFrame& frame) {
    if (input == nullptr || input_len == 0) {
        return false;
    }

    size_t out_pos = 0;
    size_t in_pos = 0;

    while (in_pos < input_len) {
        // Need at least 2 bytes for a run (count + value)
        if (in_pos + 2 > input_len) {
            return false; // truncated run header
        }

        uint8_t count = input[in_pos];
        uint8_t value = input[in_pos + 1];
        in_pos += 2;

        // --- Boundary check: prevent heap/stack buffer overflow (CWE-122) ---
        // The multiplication and addition are safe because:
        // 1. count is uint8_t (max 255)
        // 2. out_pos is bounded by FRAME_SIZE (checked below)
        // 3. We check out_pos + count > FRAME_SIZE BEFORE writing
        if (count > 0 && out_pos > FRAME_SIZE - count) {
            return false; // would overflow the fixed-size output buffer
        }

        // Fill the run
        for (uint8_t i = 0; i < count; ++i) {
            frame.pixels[out_pos++] = value;
        }
    }

    frame.size = out_pos;
    return true;
}

// Public API: decodes a compressed buffer into a frame
bool decode_frame(const std::vector<uint8_t>& compressed, DecodedFrame& frame) {
    // Reset frame state
    std::memset(frame.pixels, 0, FRAME_SIZE);
    frame.size = 0;

    if (compressed.empty()) {
        return false;
    }

    // Call the internal decoder with the raw data pointer
    return decode_rle(compressed.data(), compressed.size(), frame);
}

// Example usage (not part of the vulnerability analysis)
int main() {
    DecodedFrame frame;
    std::vector<uint8_t> compressed = { 3, 0xFF, 2, 0x00, 1, 0xAA };
    bool ok = decode_frame(compressed, frame);
    return ok ? 0 : 1;
}
