    if (r->pos + 2 > r->len) {
        return -1;
    }
    *out = (uint16_t)((r->buf[r->pos] << 8) | r->buf[r->pos + 1]);
    r->pos += 2;
    return 0;
}

static int pkt_read_bytes(pkt_reader_t *r, uint8_t *dst, size_t n) {
    if (r->pos + n > r->len) {
        return -1;
    }
    memcpy(dst, r->buf + r->pos, n);
    r->pos += n;
    return 0;
}

static int parse_tlv(pkt_reader_t *r, uint16_t *type, uint8_t *value, size_t *vlen) {
    uint16_t t, l;
    if (pkt_read_u16(r, &t) < 0 || pkt_read_u16(r, &l) < 0) {
        return -1;
    }
    if (l > MAX_HDR_LEN) {
        return -1;
    }
    if (pkt_read_bytes(r, value, l) < 0) {
