static bool read_file_block(int fd, uint64_t offset, uint32_t size, char* buffer) {
    if (lseek(fd, (off_t)offset, SEEK_SET) < 0) return false;
    ssize_t n = read(fd, buffer, size);
    return (n == (ssize_t)size);
}

