    struct stat st;
    if (stat(path, &st) != 0) return false;

    uint64_t file_size = (uint64_t)st.st_size;
    if (file_size > MAX_FILE_SIZE) return false;  // 文件过大拒绝

    int fd = open(path, O_RDONLY);
    if (fd < 0) return false;

    uint32_t block_size = MAX_BLOCK_SIZE;
    uint32_t block_count = compute_block_count(file_size, block_size);

    if (block_count == 0) {
        close(fd);
        return true;  // 空文件
