        return false;  // Not enough bytes for the length prefix.
    }

    // Read the 4-byte length prefix (little-endian).
    uint32_t strBytes = static_cast<uint32_t>(data[0]) |
                        (static_cast<uint32_t>(data[1]) << 8) |
                        (static_cast<uint32_t>(data[2]) << 16) |
                        (static_cast<uint32_t>(data[3]) << 24);

