    if (strBytes > data.size() - 4 || strBytes % 2 != 0) {
        return false;  // Length is invalid or would cause an over-read.
    }

    // Convert the byte sequence to UTF-16 code units.
    out.clear();
    for (uint32_t i = 0; i < strBytes; i += 2) {
        uint16_t codeUnit = static_cast<uint16_t>(data[4 + i]) |
                            (static_cast<uint16_t>(data[4 + i + 1]) << 8);
        out.push_back(static_cast<char16_t>(codeUnit));
