class RingBuffer {
private:
    std::vector<char> buffer_;
    size_t capacity_;
    std::atomic<size_t> read_pos_{0};
    std::atomic<size_t> write_pos_{0};
    std::atomic<bool> is_full_{false};

public:
    explicit RingBuffer(size_t cap) : buffer_(cap), capacity_(cap) {}

    // 生产者写入
    bool write(const char* data, size_t len) {
        size_t current_write = write_pos_.load(std::memory_order_relaxed);
        size_t current_read = read_pos_.load(std::memory_order_acquire);
        size_t used = (current_write >= current_read) ? 
                      (current_write - current_read) : 
                      (capacity_ - current_read + current_write);

        if (used + len > capacity_) return false;

        for (size_t i = 0; i < len; ++i) {
            size_t idx = (current_write + i) % capacity_;
            buffer_[idx] = data[i];
        }
        write_pos_.store((current_write + len) % capacity_, std::memory_order_release);
        if (used + len == capacity_) is_full_.store(true, std::memory_order_relaxed);
        return true;
    }

    // 消费者读取
    ssize_t read(char* out, size_t len) {
        size_t current_read = read_pos_.load(std::memory_order_relaxed);
        size_t current_write = write_pos_.load(std::memory_order_acquire);
        size_t used = (current_write >= current_read) ? 
                      (current_write - current_read) : 
                      (capacity_ - current_read + current_write);

        if (used == 0) return 0;
        size_t to_read = (len < used) ? len : used;

        for (size_t i = 0; i < to_read; ++i) {
            size_t idx = (current_read + i) % capacity_;
            out[i] = buffer_[idx];
        }
        read_pos_.store((current_read + to_read) % capacity_, std::memory_order_release);
        if (used != capacity_) is_full_.store(false, std::memory_order_relaxed);
        return static_cast<ssize_t>(to_read);
    }

    // 安全读取：带长度检查
    ssize_t read_safe(char* out, size_t len, size_t max_out_len) {
        if (len > max_out_len) return -1;  // 防御：限制读取长度
        return read(out, len);
    }
};

