public:
    ImageDecoder(const uint8_t* src, size_t srcLen) : data(src), length(srcLen) {}

    // Decode a run-length encoded (RLE) image into a fixed-size buffer
    // Format: [width:4][height:4][pixel data...]
    // Pixel data: repeated runs of (count:1)(value:1)
    bool decode(uint8_t* outBuffer, size_t outCapacity) {
        if (length < 8) return false;

        uint32_t width, height;
        std::memcpy(&width, data, 4);
        std::memcpy(&height, data + 4, 4);

        // Validate dimensions to prevent integer overflow in multiplication
        if (width == 0 || height == 0 || width > 4096 || height > 4096) {
            return false;
        }

        size_t expectedPixels = static_cast<size_t>(width) * height;
        if (expectedPixels > outCapacity) {
            return false;  // Output buffer too small
        }

        size_t offset = 8;
        size_t pixelsWritten = 0;

        while (offset < length && pixelsWritten < expectedPixels) {
            uint8_t runCount = data[offset++];
            uint8_t pixelValue = data[offset++];

            // Bound check: ensure we don't write beyond expectedPixels
            size_t remaining = expectedPixels - pixelsWritten;
            size_t toWrite = (runCount < remaining) ? runCount : remaining;

            std::memset(outBuffer + pixelsWritten, pixelValue, toWrite);
            pixelsWritten += toWrite;
        }

        return pixelsWritten == expectedPixels;
    }

private:
    const uint8_t* data;
    size_t length;
};

