static int ensure_capacity(struct io_buf *buf, size_t needed) {
    size_t new_cap;
    char *new_data;

    if (needed <= buf->cap)
        return 0;

    /* 计算新容量，防止整数溢出 */
    if (needed > SIZE_MAX / 2) {
        new_cap = needed;
    } else {
        new_cap = needed * 2;
    }

    /* 上限检查 */
    if (new_cap > MAX_BUF_SIZE)
        return -EOVERFLOW;

    new_data = kmalloc(new_cap, GFP_KERNEL);
    if (!new_data)
        return -ENOMEM;

    memcpy(new_data, buf->data, buf->len);
    kfree(buf->data);
    buf->data = new_data;
    buf->cap = new_cap;
    return 0;
}

static ssize_t device_write(struct file *file, const char __user *user_buf,
                            size_t count, loff_t *offset) {
    struct io_buf *buf = file->private_data;
    size_t total_needed;
    int ret;

    if (count > MAX_USER_LEN)
        return -EINVAL;

    mutex_lock(&buf_lock);

    /* 跨函数调用：总需求 = 当前长度 + 新写入长度 */
    total_needed = buf->len + count;
    if (total_needed < buf->len) {  /* 整数溢出检测 */
        ret = -EOVERFLOW;
        goto out;
    }

    ret = ensure_capacity(buf, total_needed);
    if (ret < 0)
        goto out;

    if (copy_from_user(buf->data + buf->len, user_buf, count)) {
        ret = -EFAULT;
        goto out;
    }

    buf->len += count;
    ret = count;

out:
    mutex_unlock(&buf_lock);
    return ret;
}

static int device_open(struct inode *inode, struct file *file) {
    struct io_buf *buf = kzalloc(sizeof(*buf), GFP_KERNEL);
    if (!buf)
        return -ENOMEM;

    buf->data = kmalloc(256, GFP_KERNEL);
    if (!buf->data) {
        kfree(buf);
        return -ENOMEM;
    }
    buf->cap = 256;
    buf->len = 0;
    file->private_data = buf;
    return 0;
}

