#define MAX_FIELD_LEN   128

typedef struct {
    uint8_t  data[MAX_PACKET_SIZE];
    uint16_t len;
} packet_t;

typedef struct {
    char     version[8];
    char     command[32];
    uint16_t flags;
} header_t;

static int parse_header(const packet_t *pkt, header_t *hdr)
{
    if (pkt == NULL || hdr == NULL) {
        return -1;
    }

    if (pkt->len < 3) {
        return -1;
    }

    uint16_t offset = 0;

    /* 解析版本字段（最多7字符 + 1个结尾NUL） */
    if (pkt->data[offset] == 0x00) {
        return -1;
    }
    size_t ver_len = strnlen((const char *)&pkt->data[offset],
                             pkt->len - offset);
    if (ver_len > MAX_FIELD_LEN - 1) {
        return -1;
    }
    memcpy(hdr->version, &pkt->data[offset], ver_len);
    hdr->version[ver_len] = '\0';
    offset += ver_len + 1;

    /* 解析命令字段（最多31字符 + 1个结尾NUL） */
    if (offset >= pkt->len) {
        return -1;
    }
    size_t cmd_len = strnlen((const char *)&pkt->data[offset],
                             pkt->len - offset);
    if (cmd_len > MAX_FIELD_LEN - 1) {
        return -1;
    }
    memcpy(hdr->command, &pkt->data[offset], cmd_len);
    hdr->command[cmd_len] = '\0';
    offset += cmd_len + 1;

    if (offset + 2 > pkt->len) {
        return -1;
    }
    hdr->flags = (uint16_t)(pkt->data[offset] |
                            (pkt->data[offset + 1] << 8));
    return 0;
}

