class FileBuffer {
public:
    FileBuffer() : data(nullptr), size(0) {}
    ~FileBuffer() {
        if (data) {
            free(data);
        }
    }

    bool readFile(const char* path) {
        FILE* fp = fopen(path, "rb");
        if (!fp) return false;

        fseek(fp, 0, SEEK_END);
        long len = ftell(fp);
        fseek(fp, 0, SEEK_SET);

        if (len <= 0) {
            fclose(fp);
            return false;
        }

        // 使用 RAII 管理缓冲区，避免手动 free
        char* buf = (char*)malloc(len);
        if (!buf) {
            fclose(fp);
            return false;
        }

        size_t read = fread(buf, 1, len, fp);
        fclose(fp);

        if (read != (size_t)len) {
            free(buf);
            return false;
        }

        // 释放旧数据并接管新数据
        if (data) {
            free(data);
            data = nullptr;
        }
        data = buf;
        size = len;
        return true;
    }

    const char* getData() const { return data; }
    size_t getSize() const { return size; }

private:
    char* data;
    size_t size;
};

int main(int argc, char* argv[]) {
    if (argc < 2) {
        printf("Usage: %s <file>\n", argv[0]);
        return 1;
    }

    FileBuffer fb;
    if (!fb.readFile(argv[1])) {
        printf("Failed to read file\n");
        return 1;
    }

    // 第二次读取会释放旧缓冲区并分配新缓冲区，但 RAII 确保不会双重释放
    if (!fb.readFile(argv[1])) {
        printf("Failed to re-read file\n");
        return 1;
    }

