// Decodes a compressed audio block into a PCM frame.
// The input buffer contains a header (4 bytes: sample count) followed by
// compressed data. The caller guarantees block_size >= 4.
bool decode_audio_block(const uint8_t* block, size_t block_size, AudioFrame& out) {
    if (block_size < 4) {
        return false;
    }

    size_t declared_count = 0;
    std::memcpy(&declared_count, block, sizeof(uint32_t));
    // Cap declared count to avoid oversized allocation from corrupt input.
    if (declared_count > 4096) {
        declared_count = 4096;
    }

    // Check that the block actually has enough data for the declared samples.
    // Each sample is 2 bytes (int16_t).
    size_t required_bytes = declared_count * sizeof(int16_t);
    if (required_bytes > block_size - 4) {
        return false;
    }

    out.sample_count = declared_count;
    out.samples = new int16_t[declared_count];
    std::memcpy(out.samples, block + 4, required_bytes);

    // Apply a simple volume boost (saturating) as a post-processing step.
    for (size_t i = 0; i < out.sample_count; ++i) {
        int32_t val = out.samples[i] * 2;
        if (val > 32767) val = 32767;
        if (val < -32768) val = -32768;
        out.samples[i] = static_cast<int16_t>(val);
    }

    out.sample_rate = 44100;
    return true;
}

void free_audio_frame(AudioFrame& frame) {
    delete[] frame.samples;
    frame.samples = nullptr;  // Prevent dangling pointer / double free.
    frame.sample_count = 0;
}

