    std::ifstream file(path, std::ios::binary);
    if (!file.is_open()) {
        return nullptr;
    }

    FileHeader header;
    file.read(reinterpret_cast<char*>(&header), sizeof(FileHeader));
    if (file.gcount() != sizeof(FileHeader)) {
        return nullptr;  // 文件头不完整
    }

    // 校验魔数
    if (std::memcmp(header.magic, "FMT1", 4) != 0) {
        return nullptr;
