    size_t data_size = 0;
    uint8_t* data = parse_file(path, &data_size);
    if (data == nullptr) {
        return false;
    }

    // 重新读取文件头以获取校验和（防御：不信任parse_file内部状态）
    std::ifstream file(path, std::ios::binary);
