    size_t sample_count;
    bool valid;
};

// 跨函数：解码器状态通过指针传递，帧释放分散在不同路径
static void release_frame(AudioFrame* frame) {
    if (frame->samples) {
        delete[] frame->samples;
        frame->samples = nullptr;  // 防御：释放后置 NULL，防二次释放
    }
    frame->valid = false;
}

// 解码单个数据块，成功时分配样本缓冲区
static bool decode_chunk(const uint8_t* data, size_t len, AudioFrame* out) {
    if (len < 4) return false;
    uint16_t sample_rate = (data[0] << 8) | data[1];
    uint16_t bit_depth = data[2];
    if (bit_depth != 16) return false;

    size_t count = (len - 4) / 2;  // 每样本 2 字节
    if (count == 0) return false;

    int16_t* buf = new int16_t[count];
    if (!buf) return false;
    memcpy(buf, data + 4, count * 2);

    out->samples = buf;
    out->sample_count = count;
    out->valid = true;
    return true;
}

// 主解码入口：跨函数调用，错误路径可能提前返回
bool decode_audio(const uint8_t* stream, size_t stream_len, AudioFrame* result) {
    if (!stream || !result || stream_len < 12) return false;

    // 模拟容器头部解析（此处简化）
