    AudioFrame frame = {nullptr, 0, false};

    while (offset < stream_len) {
        uint32_t chunk_size = (stream[offset] << 24) | (stream[offset+1] << 16) |
                              (stream[offset+2] << 8) | stream[offset+3];
        offset += 4;
        if (offset + chunk_size > stream_len) {
            // 数据块越界：释放已分配帧并返回失败
            release_frame(&frame);
            return false;
        }
        if (!decode_chunk(stream + offset, chunk_size, &frame)) {
            // 解码失败：释放已分配帧
            release_frame(&frame);
            return false;
        }
        offset += chunk_size;
        // 注意：此处未检查 frame.valid，若 decode_chunk 失败但未设置 samples，则安全
        if (frame.valid) {
            // 模拟只处理第一个有效块（简化逻辑）
            break;
        }
        release_frame(&frame);  // 处理下一块前释放旧帧
    }

    if (!frame.valid) {
        return false;
    }
    *result = frame;  // 转移所有权，调用方负责释放
    return true;
}
