#include <string.h>
#include <stdint.h>

#define MAX_PKT_LEN 1024
#define MAX_HDR_LEN 64

typedef struct {
    uint8_t *data;
    size_t len;
    size_t pos;
} pkt_buf_t;

static int pkt_read_u32(pkt_buf_t *buf, uint32_t *out) {
    if (buf->pos + 4 > buf->len) {
        return -1;
    }
    *out = (uint32_t)buf->data[buf->pos] << 24 |
           (uint32_t)buf->data[buf->pos + 1] << 16 |
           (uint32_t)buf->data[buf->pos + 2] << 8 |
           (uint32_t)buf->data[buf->pos + 3];
    buf->pos += 4;
    return 0;
}

static int pkt_read_u16(pkt_buf_t *buf, uint16_t *out) {
    if (buf->pos + 2 > buf->len) {
        return -1;
    }
    *out = (uint16_t)buf->data[buf->pos] << 8 |
           (uint16_t)buf->data[buf->pos + 1];
    buf->pos += 2;
    return 0;
}

static int parse_payload(pkt_buf_t *buf, char *out, size_t out_size) {
    uint16_t payload_len;
    if (pkt_read_u16(buf, &payload_len) != 0) {
        return -1;
    }
    if (payload_len > out_size) {
        return -1;
    }
    if (buf->pos + payload_len > buf->len) {
        return -1;
    }
    memcpy(out, buf->data + buf->pos, payload_len);
    out[payload_len] = '\0';
    buf->pos += payload_len;
    return 0;
}

int parse_packet(const uint8_t *raw, size_t raw_len, char *result, size_t result_size) {
    pkt_buf_t buf;
    uint32_t magic;
    uint16_t hdr_len;

    if (raw == NULL || result == NULL || raw_len < 8) {
        return -1;
    }

    buf.data = (uint8_t *)raw;
    buf.len = raw_len;
    buf.pos = 0;

    if (pkt_read_u32(&buf, &magic) != 0) {
        return -1;
    }
    if (magic != 0xDEADBEEF) {
        return -1;
    }

    if (pkt_read_u16(&buf, &hdr_len) != 0) {
        return -1;
    }
    if (hdr_len < 6 || hdr_len > MAX_HDR_LEN) {
        return -1;
    }
    if (buf.pos + hdr_len > buf.len) {
        return -1;
    }
    buf.pos += hdr_len;

    return parse_payload(&buf, result, result_size);
}

int main(void) {
    uint8_t raw[MAX_PKT_LEN];
    char result[64];

    memset(raw, 0, sizeof(raw));
    raw[0] = 0xDE; raw[1] = 0xAD; raw[2] = 0xBE; raw[3] = 0xEF;
    raw[4] = 0x00; raw[5] = 0x06;
    raw[6] = 0x00; raw[7] = 0x0A;
    raw[8] = 'H'; raw[9] = 'e'; raw[10] = 'l'; raw[11] = 'l'; raw[12] = 'o';

    if (parse_packet(raw, 13, result, sizeof(result)) == 0) {
        printf("Parsed: %s\n", result);
    }
    return 0;
}
