bool decodeRLE(const uint8_t* compressed, size_t compressedLen,
               uint8_t* output, size_t outputCapacity) {
    if (!compressed || !output) return false;

    size_t outPos = 0;
    size_t inPos = 0;

    while (inPos < compressedLen) {
        uint8_t tag = compressed[inPos++];
        uint8_t count = (tag & 0x7F) + 1;  // 1~128
        bool isRepeat = (tag & 0x80) != 0;

        // 边界检查：确保输出缓冲区不溢出
        if (outPos + count > outputCapacity) {
            return false;  // 防御：拒绝超限写入
        }

        if (isRepeat) {
            if (inPos >= compressedLen) return false;
            uint8_t value = compressed[inPos++];
            memset(output + outPos, value, count);
        } else {
            if (inPos + count > compressedLen) return false;
            memcpy(output + outPos, compressed + inPos, count);
            inPos += count;
        }
        outPos += count;
    }
    return true;
}

