// Simplified video frame decoder with macro-based accessor
#define FRAME_OFFSET(frame, x, y, stride) ((frame)->data + (y) * (stride) + (x) * (frame)->bpp)

struct VideoFrame {
    uint8_t* data;
    size_t width;
    size_t height;
    size_t stride;
    size_t bpp; // bytes per pixel
};

// Validates dimensions and allocates frame buffer
bool createFrame(VideoFrame* frame, size_t w, size_t h, size_t stride) {
    if (!frame || w == 0 || h == 0 || stride < w * frame->bpp) {
        return false;
    }
    frame->width = w;
    frame->height = h;
    frame->stride = stride;
    frame->data = new uint8_t[stride * h];
    return true;
}

// Decodes a single row from compressed source into frame
bool decodeRow(VideoFrame* frame, const uint8_t* src, size_t srcLen, size_t row) {
    if (row >= frame->height || srcLen < frame->width * frame->bpp) {
        return false;
    }
    uint8_t* dst = FRAME_OFFSET(frame, 0, row, frame->stride);
    memcpy(dst, src, frame->width * frame->bpp);
    return true;
}

// Public API: decodes a full frame from input buffer
bool decodeFrame(VideoFrame* frame, const uint8_t* compressed, size_t compressedLen) {
    // Parse header: first 4 bytes = row count, next 4 bytes = row size
    if (compressedLen < 8) return false;

    uint32_t rows = 0;
    uint32_t rowSize = 0;
    memcpy(&rows, compressed, 4);
    memcpy(&rowSize, compressed + 4, 4);

    if (rows != frame->height || rowSize != frame->width * frame->bpp) {
        return false;
    }

    const uint8_t* rowData = compressed + 8;
    size_t remaining = compressedLen - 8;

    for (size_t i = 0; i < rows; ++i) {
        if (remaining < rowSize) {
            return false;
        }
        if (!decodeRow(frame, rowData, rowSize, i)) {
            return false;
        }
        rowData += rowSize;
        remaining -= rowSize;
    }
    return true;
}

// Caller: allocates frame and invokes decoder
bool processVideo(const uint8_t* bitstream, size_t bitstreamLen, VideoFrame* outFrame) {
    if (!outFrame || !bitstream) return false;

    // Assume fixed 1920x1080 with 4-byte pixels, stride = 1920*4
    outFrame->bpp = 4;
    if (!createFrame(outFrame, 1920, 1080, 1920 * 4)) {
        return false;
    }

    bool ok = decodeFrame(outFrame, bitstream, bitstreamLen);
    if (!ok) {
        delete[] outFrame->data;
        outFrame->data = nullptr;
        return false;
    }
    return true;
}
