// 共享资源封装：RAII管理，避免手动free
class SharedBuffer {
private:
    int* data;
    size_t size;
    pthread_mutex_t lock;

public:
    SharedBuffer(size_t n) : data(nullptr), size(n) {
        pthread_mutex_init(&lock, nullptr);
        data = (int*)malloc(sizeof(int) * size);
        if (!data) {
            pthread_mutex_destroy(&lock);
            throw std::bad_alloc();
        }
    }

    ~SharedBuffer() {
        pthread_mutex_destroy(&lock);
        free(data);  // RAII析构统一释放，无双重释放
    }

    // 线程安全写入
    bool write(int value, size_t index) {
        pthread_mutex_lock(&lock);
        if (index >= size) {
            pthread_mutex_unlock(&lock);
            return false;
        }
        data[index] = value;
        pthread_mutex_unlock(&lock);
        return true;
    }

    // 线程安全读取
    int read(size_t index) {
        pthread_mutex_lock(&lock);
        if (index >= size) {
            pthread_mutex_unlock(&lock);
            return -1;
        }
        int val = data[index];
        pthread_mutex_unlock(&lock);
        return val;
    }

    // 禁止拷贝（避免浅拷贝导致双free）
    SharedBuffer(const SharedBuffer&) = delete;
    SharedBuffer& operator=(const SharedBuffer&) = delete;
};

