// 将文件大小转换为块数，带溢出保护
size_t size_to_blocks(size_t file_size) {
    // 检查乘法溢出：file_size > SIZE_MAX / BLOCK_SIZE 时溢出
    if (file_size > SIZE_MAX / BLOCK_SIZE) {
        return 0;  // 溢出则返回0，表示错误
    }
    return (file_size + BLOCK_SIZE - 1) / BLOCK_SIZE;
}

bool validate_file_size(int fd, const std::string& path) {
    struct stat st;
    if (fstat(fd, &st) != 0) {
        return false;
    }

    // 将文件大小限制为最大允许值
    const size_t max_size = MAX_FILE_SIZE_MB * 1024ULL * 1024ULL;
    if (st.st_size < 0 || static_cast<uint64_t>(st.st_size) > max_size) {
        std::cerr << "文件大小超出限制: " << path << std::endl;
        return false;
    }

    // 计算所需块数，使用安全转换
    size_t total_blocks = size_to_blocks(static_cast<size_t>(st.st_size));
    if (total_blocks == 0 && st.st_size > 0) {
        std::cerr << "块数计算溢出: " << path << std::endl;
        return false;
    }

    return true;
}

bool process_file(const std::string& path) {
    int fd = open(path.c_str(), O_RDONLY);
    if (fd < 0) {
        return false;
    }

    if (!validate_file_size(fd, path)) {
        close(fd);
        return false;
    }

    std::vector<char> buffer;
    buffer.reserve(BLOCK_SIZE);

    char temp[BLOCK_SIZE];
    ssize_t bytes_read;
    while ((bytes_read = read(fd, temp, sizeof(temp))) > 0) {
        buffer.insert(buffer.end(), temp, temp + bytes_read);
    }

    close(fd);
    return bytes_read >= 0;
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        return 1;
    }
    return process_file(argv[1]) ? 0 : 1;
