#include <vector>
#include <atomic>
#include <cstring>

class SharedBuffer {
public:
    SharedBuffer(size_t size) : data(new char[size]), len(size), read_pos(0) {}
    ~SharedBuffer() { delete[] data; }

    // 生产者：写入数据
    void write(const char* input, size_t input_len) {
        if (input_len > len) {
            std::cerr << "write: input too large\n";
            return;
        }
        std::memcpy(data, input, input_len);
        data_len.store(input_len);
        ready.store(true);
    }

    // 消费者：读取数据（带边界检查）
    int read_at(size_t offset, char* out, size_t out_cap) {
        if (!ready.load()) {
            return -1; // 数据未就绪
        }
        if (offset + out_cap > len || offset + out_cap > data_len.load()) {
            std::cerr << "read_at: out of bounds\n";
            return -1;
        }
        std::memcpy(out, data + offset, out_cap);
        return static_cast<int>(out_cap);
    }

private:
    char* data;
    size_t len;
    std::atomic<size_t> data_len{0};
    std::atomic<bool> ready{false};
    size_t read_pos; // 未使用，仅为模拟真实结构
};

// 消费者线程函数
void consumer(SharedBuffer& buf, char* out, size_t cap) {
    int n = buf.read_at(0, out, cap);
    if (n > 0) {
        std::cout << "consumer got " << n << " bytes\n";
    } else {
        std::cout << "consumer failed\n";
    }
}

int main() {
    SharedBuffer buf(64);
    char input[] = "hello world";
    buf.write(input, strlen(input));

    char output[16] = {0};
    std::thread t(consumer, std::ref(buf), output, sizeof(output));
    t.join();

    // 防御验证：尝试越界读取（应被拒绝）
    char small[4] = {0};
    if (buf.read_at(60, small, sizeof(small)) == -1) {
        std::cout << "defense works: OOB blocked\n";
    }

    return 0;
}
