static bool readPlaneData(const uint8_t*& cursor, const uint8_t* end,
                          const uint8_t*& out, size_t& outLen) {
    if (cursor + sizeof(uint32_t) > end) return false;
    uint32_t len = 0;
    std::memcpy(&len, cursor, sizeof(uint32_t));
    cursor += sizeof(uint32_t);
    if (cursor + len > end) return false;
    out = cursor;
    outLen = len;
    cursor += len;
    return true;
}

bool decodeVideoFrame(const uint8_t* input, size_t inputSize,
                      uint8_t* output, size_t outputCapacity,
                      const FrameHeader& hdr) {
    if (!input || !output) return false;
    if (hdr.width == 0 || hdr.height == 0 || hdr.planes == 0) return false;

    const uint8_t* cursor = input;
    const uint8_t* end = input + inputSize;

    // 每个平面的目标大小（模拟YUV 4:2:0布局）
    size_t planeSizes[3] = {0, 0, 0};
