        planeSizes[2] = planeSizes[0] / 4;
    }

    size_t totalNeeded = 0;
    for (int i = 0; i < hdr.planes; ++i) {
        totalNeeded += planeSizes[i];
    }
    if (totalNeeded > outputCapacity) {
        return false;   // 防御：总容量预检
    }

    size_t offset = 0;
    for (int p = 0; p < hdr.planes; ++p) {
        const uint8_t* srcData = nullptr;
        size_t srcLen = 0;
        if (!readPlaneData(cursor, end, srcData, srcLen)) {
            return false;
        }
        // 关键：跨函数调用，writeYuvPlane 内部有边界检查
        if (!writeYuvPlane(output + offset, outputCapacity - offset,
                           srcData, srcLen, planeSizes[p])) {
            return false;
        }
        offset += planeSizes[p];
    }
    return true;
