class SharedCounter {
public:
    explicit SharedCounter(int64_t initial) : counter_(initial) {}

    // Thread-safe increment with overflow protection
    bool safeIncrement(int64_t delta) {
        int64_t current = counter_.load(std::memory_order_relaxed);
        while (true) {
            if (delta > 0 && current > INT64_MAX - delta) {
                return false;  // Overflow would occur
            }
            if (delta < 0 && current < INT64_MIN - delta) {
                return false;  // Underflow would occur
            }
            if (counter_.compare_exchange_weak(
                    current, current + delta, std::memory_order_relaxed)) {
                return true;
            }
            // current is updated by compare_exchange_weak on failure
        }
    }

    int64_t get() const {
        return counter_.load(std::memory_order_relaxed);
    }

private:
