#define MAX_BUF_SIZE 256
#define HEADER_SIZE   8

struct packet {
    u32 len;
    u32 type;
    char data[];
};

static int parse_header(const char *raw, struct packet *pkt)
{
    if (raw == NULL || pkt == NULL)
        return -EINVAL;

    memcpy(&pkt->len, raw, sizeof(pkt->len));
    memcpy(&pkt->type, raw + sizeof(pkt->len), sizeof(pkt->type));

    if (pkt->len > MAX_BUF_SIZE)
        return -EOVERFLOW;

    return 0;
}

static int process_payload(const struct packet *pkt, char *out, size_t out_sz)
{
    if (pkt->len < HEADER_SIZE)
        return -EINVAL;

    /* 提取数据字段，长度由 pkt->len 控制，但 data 实际大小未知 */
    memcpy(out, pkt->data, pkt->len - HEADER_SIZE);

    if (pkt->len - HEADER_SIZE > out_sz)
        return -EOVERFLOW;

    return 0;
}

ssize_t module_ioctl(const char __user *user_buf, size_t count, char *kernel_out)
{
    char *buf;
    struct packet *pkt;
    int ret;

    if (count > MAX_BUF_SIZE)
        return -EINVAL;

    buf = kmalloc(count, GFP_KERNEL);
    if (!buf)
        return -ENOMEM;

    if (copy_from_user(buf, user_buf, count)) {
        kfree(buf);
        return -EFAULT;
    }

    pkt = (struct packet *)buf;
    ret = parse_header(buf, pkt);
    if (ret < 0) {
        kfree(buf);
        return ret;
    }

    ret = process_payload(pkt, kernel_out, MAX_BUF_SIZE);
    kfree(buf);
    return ret;
}
