        size_t rp = read_pos_.load(std::memory_order_acquire);
        size_t free_space = (rp + capacity_ - wp) % capacity_;
        if (free_space < len + 1) return false;  // 保留1字节区分空/满

        for (size_t i = 0; i < len; ++i) {
            data_[(wp + i) % capacity_] = src[i];
        }
        write_pos_.store((wp + len) % capacity_, std::memory_order_release);
        return true;
    }

    bool read(char* dst, size_t len) {
