bool ApplyGain(const int16_t* input, size_t inputSamples,
               int16_t* output, size_t outputCapacity,
               float gain) {
    if (input == nullptr || output == nullptr) {
        return false;
    }
    // Clamp gain to a sane range to avoid overflow in intermediate math.
    if (gain < 0.0f || gain > 4.0f) {
        return false;
