    uint16_t declared_count = (packet[0] << 8) | packet[1];
    size_t required_bytes = static_cast<size_t>(declared_count) * sizeof(int16_t);

    // Validate against both the actual packet size and the caller's limit
    if (required_bytes > packet_size - 4) {
        return false;  // truncated packet
    }
    if (declared_count > max_samples) {
        return false;  // exceeds caller's buffer limit
    }

    // Allocate exactly declared_count samples
