bool parse_image_header(const uint8_t* data, size_t size,
                        uint32_t& width, uint32_t& height,
                        uint32_t& bpp, size_t& buf_size) {
    if (size < 18) return false;
    const uint8_t* p = data;
    const uint8_t* end = data + size;

    width  = read_be32(p, end);
    height = read_be32(p, end);
    bpp    = read_be32(p, end);

    // 防御：拒绝明显异常或会导致溢出的输入
    if (width == 0 || height == 0 || bpp == 0 || bpp > 32) return false;
    if (width > 8192 || height > 8192) return false;

    // 关键计算：每行字节数（考虑对齐到 4 字节），再乘行数
    uint64_t row_bytes = (uint64_t(width) * bpp + 7) / 8;  // 向上取整到字节
    row_bytes = (row_bytes + 3) & ~uint64_t(3);            // 对齐到 4
    if (row_bytes > UINT32_MAX) return false;

    uint64_t total = row_bytes * height;
    if (total > 64 * 1024 * 1024) return false;  // 上限 64MB，防止资源耗尽

    buf_size = static_cast<size_t>(total);
    return true;
}

