        if (!input || input_size < 4) {
            return false;
        }

        // Parse header: [2 bytes sample_rate][2 bytes frame_size]
        uint16_t sample_rate = (input[0] << 8) | input[1];
        uint16_t frame_size = (input[2] << 8) | input[3];

        if (frame_size == 0 || frame_size > 4096) {
            return false;
        }

        // Release previous frame if exists (cleanup before reuse)
        if (last_frame_) {
            delete[] last_frame_->samples;
            delete last_frame_;
            last_frame_ = nullptr;
        }

        AudioFrame* frame = new AudioFrame();
        frame->sample_rate = sample_rate;
        frame->sample_count = frame_size;
        frame->samples = new int16_t[frame_size];

        // Copy PCM data (assumes input already contains raw samples after header)
        size_t payload_offset = 4;
        if (input_size - payload_offset < frame_size * sizeof(int16_t)) {
            delete[] frame->samples;
            delete frame;
            return false;
        }
        memcpy(frame->samples, input + payload_offset, frame_size * sizeof(int16_t));

        // Store as last frame and return
        last_frame_ = frame;
        *out_frame = frame;
        return true;
    }

