            return;
        }
        count_.fetch_sub(delta, std::memory_order_relaxed);
    }

    int get() const {
        return count_.load(std::memory_order_relaxed);
    }

private:
    std::atomic<int> count_;
};

void worker(Counter& counter, int iterations, int delta) {
    for (int i = 0; i < iterations; ++i) {
        counter.increment(delta);
        counter.decrement(delta);
    }
}

int main() {
    const int INITIAL = 1000;
    const int THREAD_COUNT = 4;
    const int ITERATIONS = 10000;
    const int DELTA = 1;

    Counter counter(INITIAL);

    std::vector<std::thread> threads;
    threads.reserve(THREAD_COUNT);

    for (int i = 0; i < THREAD_COUNT; ++i) {
        threads.emplace_back(worker, std::ref(counter), ITERATIONS, DELTA);
    }

    for (auto& t : threads) {
        t.join();
    }

    std::cout << "Final count: " << counter.get() << std::endl;
    std::cout << "Expected: " << INITIAL << std::endl;

    return 0;
}
