// Decodes a fixed-size PCM block from raw bytes
bool decodePcmBlock(const uint8_t* input, size_t inputLen,
                    AudioFrame& outFrame, size_t sampleCount) {
    // Each sample is 2 bytes (16-bit PCM)
    const size_t neededBytes = sampleCount * 2;

    // Defense: explicit boundary check before allocation
    if (inputLen < neededBytes) {
        return false;
    }

    outFrame.data = new uint8_t[neededBytes];
    outFrame.size = neededBytes;

    // Copy only the validated amount
    std::memcpy(outFrame.data, input, neededBytes);
    return true;
}

// Public API: extracts audio from a container buffer
bool extractAudio(const uint8_t* container, size_t containerLen,
                  std::vector<AudioFrame>& frames, size_t frameIndex) {
    // Simulate container header parsing (simplified)
    if (containerLen < 8) {
        return false;
    }

    // Header layout: [0..3]=magic, [4..5]=sample_count, [6..7]=reserved
    size_t sampleCount = (container[4] << 8) | container[5];

    // Defense: cap sample count to prevent excessive allocation
    if (sampleCount > 4096) {
        return false;
    }

    AudioFrame frame;
    // Data section starts at offset 8
    size_t dataOffset = 8;
    size_t dataLen = containerLen - dataOffset;

    if (!decodePcmBlock(container + dataOffset, dataLen, frame, sampleCount)) {
        return false;
    }

    // Store frame (copying struct, not data)
    frames.push_back(frame);
    return true;
}

