#define MAX_BUF_SIZE 4096
#define MAX_CHUNKS    1024

struct chunk_meta {
    size_t  len;
    void    *data;
};

static DEFINE_MUTEX(chunk_lock);
static struct chunk_meta *chunks;
static unsigned int chunk_count;

static int alloc_chunks(unsigned int count)
{
    unsigned int i;

    if (count > MAX_CHUNKS)
        return -EINVAL;

    chunks = kcalloc(count, sizeof(struct chunk_meta), GFP_KERNEL);
    if (!chunks)
        return -ENOMEM;

    for (i = 0; i < count; i++) {
        chunks[i].len = 0;
        chunks[i].data = NULL;
    }
    chunk_count = count;
    return 0;
}

static ssize_t module_write(struct file *filp, const char __user *buf,
                            size_t len, loff_t *off)
{
    unsigned int idx;
    size_t chunk_len;
    int ret;

    if (len > MAX_BUF_SIZE)
        return -EINVAL;

    mutex_lock(&chunk_lock);

    if (copy_from_user(&idx, buf, sizeof(idx))) {
        ret = -EFAULT;
        goto out_unlock;
    }

    if (idx >= chunk_count) {
        ret = -EINVAL;
        goto out_unlock;
    }

    /* 边界检查：确保 len 不会导致整数溢出 */
    if (len > MAX_BUF_SIZE - sizeof(idx)) {
        ret = -EINVAL;
        goto out_unlock;
    }

    chunk_len = len - sizeof(idx);

    chunks[idx].data = kmalloc(chunk_len, GFP_KERNEL);
    if (!chunks[idx].data) {
        ret = -ENOMEM;
        goto out_unlock;
    }

    if (copy_from_user(chunks[idx].data, buf + sizeof(idx), chunk_len)) {
        kfree(chunks[idx].data);
        chunks[idx].data = NULL;  /* 防御：释放后置 NULL */
        ret = -EFAULT;
        goto out_unlock;
    }

    chunks[idx].len = chunk_len;
    ret = chunk_len;

out_unlock:
    mutex_unlock(&chunk_lock);
    return ret;
}

static int __init module_init_func(void)
{
    return alloc_chunks(MAX_CHUNKS);
}

static void __exit module_exit_func(void)
{
    unsigned int i;

    mutex_lock(&chunk_lock);
    for (i = 0; i < chunk_count; i++) {
        kfree(chunks[i].data);
        chunks[i].data = NULL;  /* 防御：释放后置 NULL */
    }
    kfree(chunks);
    mutex_unlock(&chunk_lock);
}

module_init(module_init_func);
module_exit(module_exit_func);
MODULE_LICENSE("GPL");
