#define MAX_PKT_LEN 1024
#define MAX_HEADER_LEN 64
#define MAX_PAYLOAD_LEN (MAX_PKT_LEN - MAX_HEADER_LEN)

typedef struct {
    uint16_t type;
    uint16_t len;
    char data[MAX_PAYLOAD_LEN];
} Packet;

static int parse_packet(const char *buf, size_t buf_len, Packet *out) {
    if (buf_len < sizeof(uint16_t) * 2) {
        return -1;
    }
    out->type = (uint16_t)((buf[0] << 8) | buf[1]);
    out->len = (uint16_t)((buf[2] << 8) | buf[3]);

    if (out->len > MAX_PAYLOAD_LEN) {
        return -1;
    }
    if (buf_len < (size_t)out->len + 4) {
        return -1;
    }

    memcpy(out->data, buf + 4, out->len);
    out->data[out->len] = '\0';
    return 0;
}

static void process_packet(const char *raw, size_t raw_len) {
    Packet pkt;
    memset(&pkt, 0, sizeof(pkt));

    if (parse_packet(raw, raw_len, &pkt) != 0) {
        printf("parse failed\n");
        return;
    }

    printf("type=%u len=%u data=%s\n", pkt.type, pkt.len, pkt.data);
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        return 1;
    }

    size_t input_len = strlen(argv[1]);
    if (input_len > MAX_PKT_LEN) {
        return 1;
    }

    char *buffer = (char *)malloc(input_len + 1);
    if (!buffer) {
        return 1;
    }
    memcpy(buffer, argv[1], input_len + 1);

    process_packet(buffer, input_len);
    free(buffer);
    return 0;
}
